window.CEC_STUDY = {"sections": [{"section": 0, "name": "Definitions", "block": "A", "qcount": 0, "importance": 3, "summary": "Section 0 is the dictionary of the Code. Defined terms change how every rule applies, and the exam asks several straight definition questions - free marks if you know the exact wording.", "summary_fa": "Section 0 فرهنگ لغتِ خودِ Code است. هر defined term که این‌جا تعریف شده، معنای دقیقِ همه‌ی rule‌های بعدی را تعیین می‌کند؛ پس اگر definition را اشتباه بفهمی، کلِ جواب خراب می‌شود. آزمون هم چند سوالِ مستقیمِ definition دارد که اگر عبارتِ دقیق را بلد باشی، نمره‌اش مفت است.", "keyTables": [], "keyRules": [{"ref": "Section 0", "stars": 5, "what": "All CEC defined terms", "what_fa": "محلِ تعریفِ همه‌ی defined terms در CEC", "note": "first move for any unfamiliar word; a wrong definition corrupts the whole answer", "note_fa": "سرِ هر کلمه‌ی ناآشنا اول این‌جا را باز کن؛ اگر definition را غلط بگیری، کلِ جواب از پایه خراب می‌شود"}], "mustKnow": ["Bonding: a low-impedance path, permanently and effectively established, to carry fault current and connect non-current-carrying metal parts (memorize the full sentence).", "Grounding: a connection to earth or to a conducting body serving in place of earth.", "Feeder: conductors from service box to the branch-circuit overcurrent device. Branch circuit: from the final OCPD to the outlet(s).", "Overcurrent protects WIRES (fuse/breaker); overload protects the MOTOR (thermal). Most-confused pair on the exam.", "Ampacity: current a conductor can carry continuously without exceeding its temperature rating.", "Voltage classes: Extra-Low <=30 V; Low-voltage >30 to 750 V; High-voltage >750 V (boundaries inclusive of the stated value).", "Dwelling unit / continuous load / duty cycle (continuous, intermittent, periodic, short-time) are all defined here."], "mustKnow_fa": ["Bonding یعنی یک مسیرِ کم‌امپدانس که به‌طور دائمی و موثر برقرار شده تا هم جریانِ خطا (fault current) را عبور بدهد و هم قطعاتِ فلزیِ غیرحاملِ جریان را به هم متصل کند؛ این جمله را کلمه‌به‌کلمه حفظ کن چون عینِ همین در سوال می‌آید.", "Grounding یعنی اتصال به زمین، یا به جسمی رسانا که جای زمین می‌نشیند.", "Feeder همان هادی‌هایی است که از service box تا وسیله‌ی اضافه‌جریانِ مدارِ انشعابی می‌روند؛ و Branch circuit از همان آخرین OCPD شروع و تا پریزها ادامه پیدا می‌کند.", "Overcurrent از سیم‌ها مراقبت می‌کند (با fuse یا breaker)، ولی overload از موتور مراقبت می‌کند (حرارتی)؛ این دو پرتکرارترین جفتِ اشتباه‌گیرنده‌ی آزمون هستند.", "Ampacity یعنی جریانی که یک هادی می‌تواند به‌طور پیوسته حمل کند بدون اینکه از رده‌ی دماییِ خودش بالا بزند.", "کلاس‌های ولتاژ: Extra-Low یعنی 30 V و پایین‌تر؛ Low-voltage یعنی بالای 30 تا 750 V؛ High-voltage یعنی بالای 750 V — و یادت باشد خودِ عددِ مرزی هم جزوِ همان رده حساب می‌شود.", "اصطلاحاتِ dwelling unit، continuous load و duty cycle (یعنی continuous، intermittent، periodic، short-time) همگی همین‌جا در Section 0 تعریف شده‌اند."], "traps": ["Bonding definition trap: a version with a word dropped (e.g. 'permanently' or 'low-impedance' missing) is the wrong answer.", "Feeder vs branch-circuit: feeder ends at the branch OCPD; branch starts there. Trips up ~90% of electricians.", "Overcurrent vs overload: don't swap them - wires vs motor.", "Voltage boundaries are inclusive: 30 V = Extra-Low, 750 V is the top of Low (not High); '1000 V = Low' in older framing - read the exact code value.", "A defined term may override your field/site meaning - always check Section 0 first."], "traps_fa": ["دامِ definition برای Bonding: گزینه‌ای که یک کلمه‌اش حذف شده (مثلاً 'permanently' یا 'low-impedance' نباشد) همان جوابِ غلط است؛ هر clause را با دقت چک کن.", "Feeder و branch circuit را قاطی نکن: feeder دقیقاً سرِ branch OCPD تمام می‌شود و branch از همان‌جا شروع می‌شود؛ این تقریباً 90٪ برق‌کارها را گول می‌زند.", "Overcurrent و overload را جابه‌جا نکن — یکی مالِ wires است و دیگری مالِ motor.", "مرزهای voltage شاملِ خودِ عدد هم می‌شوند: 30 V داخلِ Extra-Low است و 750 V سقفِ Low است نه شروعِ High؛ در نسخه‌های قدیمی‌تر '1000 V = Low' بوده، پس همیشه عددِ دقیقِ همان نسخه‌ی Code را بخوان.", "یک defined term ممکن است برداشتِ کارگاهی و میدانیِ تو را باطل کند؛ پس همیشه اول Section 0 را چک کن، بعد قضاوت."], "mnemonic": "Bonding = Big Permanent Low-impedance path. OverCurrent = Conductors; overLoad = motor (Load).", "mnemonic_fa": "Bonding را با سه کلمه به‌خاطر بسپار: مسیرِ دائمیِ کم‌امپدانس (Big Permanent Low-impedance). و برای آن جفتِ گول‌زننده: OverCurrent مالِ هادی‌ها (Conductors) است، overLoad مالِ موتور (Load).", "method": ["Any unfamiliar or pivotal term -> Section 0 BEFORE reading the rule.", "For definition questions, match every clause of the option to the exact code sentence - the trap is one dropped/changed word.", "Use the Index if the word could live in a specific section too."], "method_fa": ["سرِ هر defined term ناآشنا یا کلیدی، قبل از اینکه rule را بخوانی برو Section 0.", "در سوالاتِ definition، تک‌تکِ clause‌های گزینه را با جمله‌ی دقیقِ Code مقابله کن؛ دامش معمولاً یک کلمه‌ی حذف‌شده یا عوض‌شده است.", "اگر آن کلمه احتمالاً در یک Section خاص هم آمده، از Index کمک بگیر تا جای دومش را هم پیدا کنی."], "examples": ["OCC-062"], "keywords": [{"kw": "\"bonding\"", "jump": "Section 0 definitions", "why": "low-impedance permanent path - memorize verbatim", "why_fa": "low-impedance permanent path؛ این definition را کلمه‌به‌کلمه حفظ کن", "stars": 5}, {"kw": "\"feeder vs branch circuit\"", "jump": "Section 0 definitions", "why": "service box->branch OCPD vs final OCPD->outlet", "why_fa": "feeder از service box تا branch OCPD؛ branch از همان آخرین OCPD تا outlet", "stars": 5}, {"kw": "\"overcurrent vs overload\"", "jump": "Section 0 definitions", "why": "protects wires vs protects motor", "why_fa": "یکی مراقبِ wires است، دیگری مراقبِ motor", "stars": 5}, {"kw": "\"ampacity\"", "jump": "Section 0 definitions", "why": "continuous current without exceeding temp rating", "why_fa": "current پیوسته بدون بالا زدن از temperature rating یک conductor", "stars": 4}, {"kw": "\"voltage / voltage-to-ground / voltage classes\"", "jump": "Section 0 definitions", "why": "Extra-Low/Low/High boundaries are inclusive", "why_fa": "مرزهای Extra-Low/Low/High شاملِ خودِ عدد هم می‌شوند", "stars": 4}, {"kw": "\"dwelling unit\"", "jump": "Section 0 definitions", "why": "controls Section 8 load calcs and Rule 2-110", "why_fa": "load calcs در Section 8 و Rule 2-110 را همین definition کنترل می‌کند", "stars": 4}, {"kw": "\"continuous load\"", "jump": "Section 0 definitions", "why": "triggers 125% sizing (Rule 8-104)", "why_fa": "اگر load از نوع continuous باشد، sizing با 125٪ فعال می‌شود (Rule 8-104)", "stars": 4}, {"kw": "\"grounding\"", "jump": "Section 0 definitions", "why": "earth/conducting-body connection - distinct from bonding", "why_fa": "connection به earth یا conducting body؛ با bonding فرق دارد، قاطی نکن", "stars": 4}, {"kw": "\"duty cycle (continuous/intermittent/periodic/short-time)\"", "jump": "Section 0 definitions", "why": "periodic = intermittent duty, regularly recurrent", "why_fa": "periodic یعنی intermittent duty که به‌طور منظم تکرار می‌شود", "stars": 3}, {"kw": "\"approved / labelled / listed\"", "jump": "Section 0 definitions", "why": "acceptance terms that change a rule's force", "why_fa": "acceptance terms هستند که قوّتِ یک rule را کم و زیاد می‌کنند", "stars": 2}, {"kw": "\"any unfamiliar defined term\"", "jump": "Section 0 definitions", "why": "golden first move before reading the rule", "why_fa": "بهترین حرکتِ اول، قبل از خواندنِ خودِ rule", "stars": 5}]}, {"section": 2, "name": "General & Working Space", "block": "A", "qcount": 18, "importance": 4, "summary": "Section 2 sets the universal rules: working space, headroom, voltage-to-ground, enclosure selection and gas-meter clearance. Easy, high-frequency lookups that protect free marks across the whole exam.", "summary_fa": "Section 2 همان قوانین پایه و عمومی است که همه‌جای Code به آن تکیه دارد: working space (فضای کار)، headroom (ارتفاع آزاد) بالای تجهیزات، voltage-to-ground، انتخاب نوع enclosure (محفظه) و فاصله از gas meter (کنتور گاز). این‌ها سوال‌های ساده و پرتکرارند؛ کافی است جای table و rule را بلد باشی تا نمره‌اش را مفت ببری.", "keyTables": [{"ref": "Table 65", "stars": 5, "what": "Enclosure type selection (1, 3R, 4, 4X...)", "what_fa": "از روی این Table نوع enclosure (محفظه) را انتخاب می‌کنی: Type 1، 3R، 4، 4X و غیره", "use": "match enclosure to the location: wet, corrosive, outdoor, dust", "use_fa": "اول شرایط محل را بسنج (wet؟ corrosive؟ outdoor؟ dust؟) بعد ارزان‌ترین Type که همه‌ی آن شرایط را پوشش بدهد انتخاب کن"}, {"ref": "Table 56", "stars": 4, "what": "Working space for exposed live parts >750 V", "what_fa": "working space برای exposed live parts (قطعات برقدارِ بدون پوشش) در voltage بالای 750 V", "use": "enter with line-to-ground voltage AND the facing-surface condition", "use_fa": "با دو ورودی وارد Table شو: line-to-ground voltage و وضعیت facing surface (مثلاً grounded wall یا live parts). یادت باشد اول ولتاژ را به line-to-ground تبدیل کنی"}], "keyRules": [{"ref": "Rule 2-308", "stars": 5, "what": "Working space / clearance / headroom about equipment", "what_fa": "working space، clearance (فاصله‌ی مجاز) و headroom اطراف تجهیزات", "note": "1 m front (2-308 1); 2.2 m headroom (2-308 5); HV via Table 56 (2-308 4) - guaranteed exam topic", "note_fa": "1 m جلوی تجهیزات (2-308 1)؛ 2.2 m headroom بالای سر (2-308 5)؛ برای high voltage برو سراغ Table 56 (2-308 4). این Rule تقریباً همیشه در آزمون می‌آید، حفظش کن"}, {"ref": "Rule 2-110", "stars": 4, "what": "Max voltage-to-ground in a dwelling = 150 V", "what_fa": "در dwelling، voltage-to-ground نباید از 150 V بیشتر شود", "note": "exception only if calc load >250 kVA AND qualified maintenance staff", "note_fa": "استثنایش فقط وقتی است که هم calculated load بالای 250 kVA باشد و هم qualified maintenance staff (کارکنانِ نگهداریِ واجد شرایط) حضور داشته باشند؛ هر دو شرط با هم لازم است"}, {"ref": "Rule 2-328", "stars": 3, "what": "Clearance of equipment from gas metering/relief devices", "what_fa": "clearance تجهیزات برقی از gas meter و pressure-relief devices (شیرهای تخلیه‌ی فشار)", "note": "numeric values live in Appendix B, not the rule body", "note_fa": "خودِ عددها در Appendix B هستند نه در متنِ rule؛ این دقیقاً همان‌جایی است که خیلی‌ها گیر می‌کنند"}, {"ref": "Rule 2-130", "stars": 2, "what": "Flame-spread (FT) rating of cables in buildings", "what_fa": "flame-spread (FT) rating برای cable‌های داخل ساختمان", "note": "FT ratings explained in Appendix B; references the NBC", "note_fa": "توضیح FT ratings در Appendix B آمده و خودِ rule هم به NBC ارجاع می‌دهد"}, {"ref": "Appendix B", "stars": 3, "what": "Plain-language notes, gas-meter distances, FT ratings", "what_fa": "notes توضیحیِ ساده، gas-meter distances و FT ratings", "note": "the 'note of the day' - 6-7 questions exam-wide live here", "note_fa": "همان Appendix طلاییِ امتحان؛ نزدیک 6 تا 7 سوالِ کل آزمون از همین‌جا درمی‌آید، پس دستِ‌کم نگیرش"}], "mustKnow": ["General working space in front of equipment = 1.0 m with secure footing (Rule 2-308 1).", "Minimum headroom over switchboards/MCCs with exposed live parts = 2.2 m (2-308 5).", "Dwelling branch circuits: max 150 V to ground (2-110); 120/240 V system = 120 V to ground, complies.", "Enclosure suffix 'X' = corrosion resistant; '3R' = rainproof outdoor; '4' = watertight/hose; '4X' = watertight + corrosive.", "Transformer working space needed only when >50 kVA (exactly 50 kVA = none).", "Gas-meter clearance (Appendix B): natural gas ~1 m, propane ~3 m, 0.3 m with a listed regulator; arc-producing equipment kept farther."], "mustKnow_fa": ["working space عمومیِ جلوی تجهیزات 1.0 m است، آن هم با secure footing (جای پای محکم) (Rule 2-308 1).", "headroom بالای سر روی switchboard و MCC که exposed live parts دارند حداقل 2.2 m است (2-308 5).", "در dwelling، voltage-to-ground حداکثر 150 V است (2-110)؛ سیستم رایجِ 120/240 V نسبت به زمین فقط 120 V دارد، پس راحت در محدوده است.", "رمزِ پسوندهای enclosure: 'X' یعنی corrosion resistant، '3R' یعنی rainproof outdoor، '4' یعنی watertight و مقاوم به hose، و '4X' یعنی watertight به‌علاوه‌ی corrosive.", "working space برای transformer فقط وقتی لازم می‌شود که از 50 kVA بیشتر باشد؛ دقیقاً 50 kVA هنوز نیازی ندارد (مرز شامل خودِ عدد است).", "gas-meter clearance (Appendix B): natural gas حدود 1 m، propane حدود 3 m، و با یک listed regulator تا 0.3 m؛ arc-producing equipment را باید دورتر هم نگه داری."], "traps": ["Table 56 uses LINE-TO-GROUND voltage - convert first (divide 3-phase by root3); don't re-divide an already-converted value.", "Voltage-class boundaries are inclusive: 'not exceeding X' includes X (exactly 50 kVA transformer = no working space required).", "Gas-meter distance is an Appendix B value, NOT in the Rule 2-328 body - students stop at the rule and miss it.", "Don't confuse Type 3R (rain only) with Type 4 (splash/hose) or 4X (splash + corrosive); read the exact location words.", "Dwelling 150 V rule is 2-110, not 2-130 (2-130 is flame-spread)."], "traps_fa": ["Table 56 ورودی‌اش line-to-ground voltage است؛ اول تبدیل کن (3-phase voltage را تقسیم بر root3) ولی حواست باشد عددی را که قبلاً تبدیل شده دوباره تقسیم نکنی — این دامِ کلاسیکِ سرِ امتحان است.", "مرزهای voltage class شاملِ خودِ عدد هم می‌شوند؛ 'not exceeding X' یعنی خودِ X هم داخلش است (transformerِ دقیقاً 50 kVA هنوز working space لازم ندارد).", "عددِ gas-meter distance در Appendix B است نه در متنِ Rule 2-328؛ خیلی‌ها سرِ rule می‌ایستند و Appendix را نمی‌بینند و سوال را می‌بازند.", "Type 3R (فقط rain) را با Type 4 (splash و hose) یا 4X (splash به‌علاوه‌ی corrosive) قاطی نکن؛ دقیقاً به location words در صورتِ سوال نگاه کن.", "Rule 150 V مسکونی همان Rule 2-110 است نه 2-130؛ یادت باشد 2-130 مالِ flame-spread است."], "mnemonic": "Working space = ONE in front, TWO-point-TWO up. 'X' = corroXion; '3R' = Rain; '4' = wash (hose); '4X' = wash + corroXion.", "mnemonic_fa": "working space را این‌طوری حفظ کن: «یک متر جلو، 2.2 متر بالا». رمزِ enclosure‌ها هم: 'X' = corroXion، '3R' = Rain، '4' = wash با hose، و '4X' = wash به‌علاوه‌ی corroXion.", "method": ["Spot the keyword: working space -> Rule 2-308; enclosure -> Table 65; voltage-to-ground -> Rule 2-110; gas meter -> Rule 2-328 + Appendix B.", "For working space, first decide the voltage class: <=750 V uses the flat 1 m; >750 V goes to Table 56 with line-to-ground voltage.", "For enclosures, list the location conditions (wet? corrosive? outdoor? dust?) and match the lowest Type in Table 65 that covers all of them.", "If the number isn't in the rule body, jump to Appendix B (gas clearances, FT ratings)."], "method_fa": ["اول از روی keyword مسیرت را پیدا کن: working space برو Rule 2-308؛ enclosure برو Table 65؛ voltage-to-ground برو Rule 2-110؛ gas meter برو Rule 2-328 به‌علاوه‌ی Appendix B.", "برای working space اول voltage class را معلوم کن: 750 V و پایین‌تر همان 1 m ثابت است؛ بالای 750 V باید بروی Table 56 و با line-to-ground voltage واردش شوی.", "برای enclosure، شرایط محل را لیست کن (wet؟ corrosive؟ outdoor؟ dust؟) و پایین‌ترین Type در Table 65 را بردار که همه‌ی آن شرایط را پوشش بدهد — نه بیشتر، نه کمتر.", "هر وقت عدد را در متنِ rule پیدا نکردی، یک‌راست برو Appendix B (همان‌جا gas clearances و FT ratings را پیدا می‌کنی)."], "examples": ["S02-002", "S02-004", "S02-007", "S02-013", "S02-017", "S02-018"], "keywords": [{"kw": "\"enclosure type (3R, 4, 4X, 5)\"", "jump": "Table 65", "why": "selects enclosure by wet/corrosive/dust/outdoor conditions", "why_fa": "نوع enclosure را بر اساس شرایط محل (wet، corrosive، dust، outdoor) انتخاب می‌کنی", "stars": 5}, {"kw": "\"working space / clearance in front of\"", "jump": "Rule 2-308 1) + Table 56", "why": "1 m general; Table 56 (line-to-ground) above 750 V", "why_fa": "حالت عمومی 1 m است؛ ولی بالای 750 V باید بروی Table 56 و با line-to-ground voltage واردش شوی", "stars": 5}, {"kw": "\"voltage to ground in a dwelling\"", "jump": "Rule 2-110", "why": "150 V max; exception >250 kVA + qualified staff", "why_fa": "سقفش 150 V است؛ exception فقط بالای 250 kVA و آن هم با qualified staff", "stars": 4}, {"kw": "\"headroom of working space\"", "jump": "Rule 2-308 5)", "why": "2.2 m over switchboards/MCCs with exposed live parts", "why_fa": "بالای switchboard و MCC با exposed live parts باید 2.2 m headroom باشد", "stars": 4}, {"kw": "\"high-voltage / >750 V working space\"", "jump": "Rule 2-308 4) + Table 56", "why": "keyed to voltage class and facing surface", "why_fa": "اندازه‌اش به voltage class و facing surface بستگی دارد، نه یک عدد ثابت", "stars": 4}, {"kw": "\"corrosive area / splash of water\"", "jump": "Table 65 (Type 4X / 3X)", "why": "'X' suffix = added corrosion resistance", "why_fa": "هر جا suffix 'X' دیدی یعنی corrosion resistance اضافی اضافه شده", "stars": 4}, {"kw": "\"gas meter clearance / pressure-relief device\"", "jump": "Rule 2-328 + Appendix B", "why": "numeric distances are in Appendix B", "why_fa": "خودِ عددِ distances در Appendix B است، در متنِ rule پیدایش نمی‌کنی", "stars": 3}, {"kw": "\"transformer working space\"", "jump": "Rule 2-308", "why": "required only when transformer >50 kVA", "why_fa": "فقط وقتی لازم است که transformer از 50 kVA بیشتر باشد", "stars": 3}, {"kw": "\"cable flame rating / FT1 FT4\"", "jump": "Rule 2-130 + Appendix B", "why": "combustible vs non-combustible construction", "why_fa": "بستگی دارد به اینکه construction از نوع combustible است یا non-combustible", "stars": 2}, {"kw": "\"deviation / special permission\"", "jump": "Rule 2-030", "why": "approved before work, that installation only", "why_fa": "همان deviation؛ special permission که قبل از شروعِ کار approved می‌شود و فقط برای همان installation اعتبار دارد", "stars": 2}, {"kw": "\"disconnecting means / open position indication\"", "jump": "Rule 2-308 + 14-500 series", "why": "must positively indicate OFF (a 3-way switch cannot)", "why_fa": "disconnect باید قطعی و مطمئن وضعیت OFF را نشان بدهد؛ یک 3-way switch از پسش برنمی‌آید", "stars": 2}, {"kw": "\"illumination of equipment\"", "jump": "Rule 2-320", "why": "lighting at electrical rooms - do not confuse with 2-328", "why_fa": "illumination اتاق‌های برق است؛ مراقب باش با 2-328 (gas meter) قاطی نکنی", "stars": 1}]}, {"section": 4, "name": "Conductors & Ampacity", "block": "C", "qcount": 34, "importance": 5, "summary": "Pick the correct ampacity table by metal + install method, then multiply by grouping (5C) and ambient (5A) corrections, and cap at the terminal/lowest temperature. Pure lookup-and-multiply marks once the table grid is automatic.", "keyTables": [{"ref": "Table 1", "stars": 4, "what": "Copper ampacity in FREE AIR", "use": "free-air copper only; start in the 90°C column", "what_fa": "ampacity (ظرفیت جریان‌دهی) یک copper conductor در free air", "use_fa": "فقط برای copper در free air؛ کارت را همیشه از the 90°C column شروع کن"}, {"ref": "Table 2", "stars": 5, "what": "Copper ampacity in raceway/cable", "use": "default Cu table; pick the column = conductor temp (60/75/90)", "what_fa": "ampacity یک copper conductor داخل raceway/cable", "use_fa": "default Cu table؛ column آن را برابر conductor temp خودِ هادی (60/75/90) بگیر — بیشترِ سؤال‌های ampacity همین‌جا حل می‌شود"}, {"ref": "Table 3", "stars": 3, "what": "Aluminum ampacity in FREE AIR", "use": "the rare free-air aluminum combo the exam loves", "what_fa": "ampacity یک aluminum conductor در free air", "use_fa": "همان ترکیبِ کمیابِ «aluminum در free air» که آزمون عاشقِ گیر انداختنت با آن است — حواست باشد سراغ Table 1 نروی"}, {"ref": "Table 4", "stars": 3, "what": "Aluminum ampacity in raceway/cable", "use": "raceway Al; same column logic as Table 2", "what_fa": "ampacity یک aluminum conductor داخل raceway/cable", "use_fa": "aluminum داخل raceway؛ منطق انتخابِ column دقیقاً مثل Table 2 است (column = conductor temp)"}, {"ref": "Table 5C", "stars": 5, "what": "Grouping/bundling derate (>3 current-carrying)", "use": "4-6=0.80, 7-24=0.70, 25-42=0.60; count power+lighting only", "what_fa": "ضریبِ derate به‌خاطر grouping/bundling هادی‌ها (وقتی بیش از 3 تا current-carrying conductor کنار هم باشند)", "use_fa": "4-6=0.80، 7-24=0.70، 25-42=0.60؛ یادت باشد فقط current-carrying conductors (power و lighting) را می‌شماری، نه bonding و نه نولِ متعادل (balanced neutral)"}, {"ref": "Table 5A", "stars": 5, "what": "Ambient temperature correction (>30°C)", "use": "pick by the conductor insulation column; round the ambient temp UP to next listed row", "what_fa": "ضریبِ ambient correction (تصحیح دمای محیط، وقتی ambient بالای 30°C است)", "use_fa": "ضریب را از the insulation column هادی (60/75/90) بردار؛ و the ambient temp را همیشه به سطر بالاترِ بعدی گرد کن، UP (به نفع احتیاط، رو به بالا)"}, {"ref": "Table 36B", "stars": 3, "what": "Copper neutral-supported (NS) service cable", "use": "overhead service/feeder Cu; read down to size ≥ load", "what_fa": "copper neutral-supported (NS) service cable", "use_fa": "برای overhead service/feeder از جنس copper؛ توی جدول پایین برو تا به سایزی برسی که ampacity آن ≥ load باشد"}, {"ref": "Table 36A", "stars": 2, "what": "Aluminum neutral-supported (NS) service cable", "use": "overhead service/feeder Al (quadruplex)", "what_fa": "aluminum neutral-supported (NS) service cable", "use_fa": "برای overhead service/feeder از جنس aluminum (همان quadruplex)"}, {"ref": "Table 12", "stars": 3, "what": "Flexible cord / equipment wire / portable-power-cable ampacity", "use": "TEW, GTF, elevator ETP, DLO; cords use 11A/11B, portable power 12A", "what_fa": "ampacity یک flexible cord / equipment wire / portable-power-cable", "use_fa": "برای TEW، GTF، elevator ETP و DLO؛ یادت باشد cords را از 11A/11B می‌خوانی و portable power را از 12A"}, {"ref": "Appendix D — D8/D10/D11", "stars": 2, "what": "Underground direct-buried / spaced ampacity", "use": "Rule 4-004 1)d) routes here for buried/spaced configurations", "what_fa": "ampacity حالتِ underground direct-buried / spaced", "use_fa": "وقتی Rule 4-004 1)d) برای حالت‌های buried یا spaced تو را به این بخش می‌فرستد، ampacity را از همین دیاگرام‌های Appendix D دربیاور"}], "keyRules": [{"ref": "Rule 4-004", "stars": 5, "what": "How to determine ampacity / pick the table & corrections", "note": "Governs nearly every Section 4 question; 1)c)=raceway, 1)d)=underground, 5)=NS service; subrules 6&7 say which conductors count for derate", "what_fa": "نقشهٔ راهِ تعیینِ ampacity / این‌که کدام table و کدام correction factors را برداری", "note_fa": "Rule 4-004 عملاً بالای سرِ تقریباً همهٔ سؤال‌های Section 4 است؛ 1)c)=داخل raceway، 1)d)=underground، 5)=NS service؛ و بندهای 6 و 7 تکلیفت را روشن می‌کنند که برای derate کدام conductors شمرده می‌شوند. اول این را پیدا کن، بعد بقیه"}, {"ref": "Rule 4-006", "stars": 5, "what": "Terminal temperature limitation", "note": "Ampacity capped at the LOWEST marked termination temp; unmarked = 60°C if ≤100A (≤#1), 75°C if >100A. The cable's 90 is bait", "what_fa": "terminal temperature limitation (محدودیتِ دمای سرِ اتصال)", "note_fa": "ampacity نهایی به پایین‌ترین terminal temp علامت‌خورده سقف می‌خورد؛ اگر unmarked باشد: 60°C برای ≤100A (یعنی ≤#1) و 75°C برای >100A. آن 90°C روی cable فقط طعمه است — تا وقتی terminal روی 75 باشد، عدد 90 به دردت نمی‌خورد"}, {"ref": "Rule 4-038", "stars": 4, "what": "Mixed temperature ratings in one raceway", "note": "Size every conductor on the LOWEST temp rating present; compute each conductor separately, never add", "what_fa": "mixed temperature ratings در یک raceway", "note_fa": "همهٔ conductors را با پایین‌ترین temp rating موجود در همان raceway سایز کن؛ و ampacity هر conductor را جداگانه حساب کن — هیچ‌وقت ampacityها را با هم جمع نکن"}, {"ref": "Rule 4-016", "stars": 3, "what": "Neutral/identified conductor temp rating", "note": "Neutral insulation must be NOT LESS than the ungrounded conductors' rating", "what_fa": "temperature rating یک neutral / identified conductor", "note_fa": "insulation rating یک neutral نباید از rating هادی‌های ungrounded کمتر باشد — یعنی neutral حداقل هم‌رتبهٔ فازهاست"}, {"ref": "Rule 4-036", "stars": 2, "what": "Conductor colour identification", "note": "3-phase colour-coded sequence A=red, B=black, C=blue", "what_fa": "conductor colour identification (کدِ رنگیِ شناسایی هادی‌ها)", "note_fa": "ترتیبِ colour سه‌فاز را حفظ کن: A=red، B=black، C=blue"}, {"ref": "Rule 8-104", "stars": 3, "what": "Continuous-load 125% (referenced from Sec 8)", "note": "For continuous loads, conductor & breaker sized at 125% of the load before applying ampacity", "what_fa": "continuous load و ضریبِ 125% (که از Section 8 وام گرفته می‌شود)", "note_fa": "برای continuous load، اول load را در 125% ضرب کن، بعد با آن عدد سراغ سایز کردنِ conductor و breaker برو — یعنی 125% پیش از کارِ ampacity انجام می‌شود"}], "mustKnow": ["Table grid: free-air Cu=T1, raceway Cu=T2, free-air Al=T3, raceway Al=T4. Exam loves the rare free-air aluminum (T3).", "Table 5C grouping: 4-6=0.80, 7-24=0.70, 25-42=0.60. Applies only when MORE than 3 current-carrying conductors.", "Table 5A ambient: only when ambient >30°C; pick the factor by the insulation column (60/75/90) and round the temperature UP.", "Multiply BOTH correction factors when both apply (grouping × ambient); order does not matter.", "Count current-carrying conductors only: bonding/ground never counts; a balanced 3-wire neutral does not count.", "Rule 4-038: different temp ratings in one raceway -> use the lowest rating column for ALL of them.", "Rule 4-006 termination cap: 90°C cable on a 75°C breaker is held to the 75°C ampacity.", "NS overhead service: Cu=Table 36B, Al=Table 36A. Min service conductor #10 Cu / #8 Al (Rule 6-302)."], "traps": ["Using the cable's 90°C column when the termination is marked 75°C (Rule 4-006) — the lower governs.", "Choosing Table 3 (free-air Al) for a copper conductor that merely has an aluminum sheath — the current-carrying metal sets the table (S04-001).", "Mixed-temp raceway: forgetting the R90 conductor must be read in the 75°C column when a 75°C conductor shares the raceway (Rule 4-038).", "Derating free-air conductors when no spacing is given — grouping in free air only applies if spacing < 25% of the largest cable diameter; if not stated, do NOT derate.", "Counting bonding or a balanced neutral as current-carrying when applying Table 5C.", "Forgetting to round the ambient temperature UP to the next listed row before reading Table 5A.", "On 'minimum size' questions: divide the load by the derate factors to get the required TABLE ampacity, then pick the next size up (S04-034)."], "mnemonic": "Tables 1&2 = Copper, 3&4 = Aluminum; Tables 1&3 = free Air, 2&4 = raceway. So free-air copper = T1, raceway aluminum = T4. Corrections: '5C = Count' (grouping), '5A = Air temp' (ambient).", "method": ["1. Pick the base table: metal (Cu/Al) + install (free-air vs raceway/cable) -> T1/T2/T3/T4 (or 36A/B for NS, T12 for cords/equip wire, App D for underground).", "2. Read the base ampacity in the column = conductor temp rating; if mixed ratings share the raceway use the LOWEST (Rule 4-038).", "3. Apply termination cap (Rule 4-006): if a terminal is marked lower, drop to that column.", "4. Grouping derate (Table 5C) if >3 current-carrying conductors; count power/lighting only.", "5. Ambient correction (Table 5A) if ambient >30°C; round temp up, pick by insulation column.", "6. Multiply base × grouping × ambient. For 'minimum size', divide the required load by the factors first, then pick the next standard size up."], "examples": ["S04-001", "S04-003", "S04-011", "S04-021", "S04-034"], "keywords": [{"kw": "\"ampacity / max current a conductor can carry\"", "jump": "Tables 1-4", "why": "free air: T1 Cu / T3 Al; raceway/cable: T2 Cu / T4 Al; start 90°C column", "stars": 5, "why_fa": "free air: T1 copper / T3 aluminum؛ داخل raceway/cable: T2 copper / T4 aluminum؛ و همیشه کار را از the 90°C column شروع کن"}, {"kw": "\"in a raceway / conduit / cable\" + copper", "jump": "Table 2", "why": "default copper ampacity table; column = conductor temp", "stars": 5, "why_fa": "default copper ampacity table؛ column آن را برابر conductor temp بگیر"}, {"kw": "\"in free air\" + copper", "jump": "Table 1", "why": "free-air copper, NOT Table 3 (that's free-air aluminum)", "stars": 4, "why_fa": "free-air copper؛ مراقب باش سراغ Table 3 نروی، آن مالِ free-air aluminum است"}, {"kw": "\"in free air\" + aluminum", "jump": "Table 3", "why": "the rare free-air-aluminum combo the exam targets", "stars": 3, "why_fa": "همان ترکیبِ کمیابِ free-air aluminum که آزمون مخصوصاً نشانه می‌گیرد"}, {"kw": "\"in a raceway\" + aluminum", "jump": "Table 4", "why": "raceway aluminum ampacity", "stars": 3, "why_fa": "ampacity یک aluminum داخل raceway"}, {"kw": "\"more than 3 conductors\" / \"X conductors\" / bundling", "jump": "Table 5C", "why": "grouping derate 4-6=0.80, 7-24=0.70, 25-42=0.60", "stars": 5, "why_fa": "grouping derate: 4-6=0.80، 7-24=0.70، 25-42=0.60"}, {"kw": "\"ambient ___ °C\" (above 30°C)", "jump": "Table 5A", "why": "temperature correction; pick by insulation column, round temp UP", "stars": 5, "why_fa": "ambient correction؛ از the insulation column بردار و دما را رو به بالا، UP، گرد کن"}, {"kw": "\"how to pick the table / determine ampacity / which conductors count\"", "jump": "Rule 4-004", "why": "master ampacity rule; subrules set raceway/underground/NS and the count rules", "stars": 5, "why_fa": "master ampacity rule؛ subrulesها تکلیفِ raceway/underground/NS و قاعدهٔ count را روشن می‌کنند"}, {"kw": "\"terminated at / terminal marked X°C\"", "jump": "Rule 4-006", "why": "cap ampacity at the lowest terminal temp; 90 cable on 75 breaker = 75 value", "stars": 5, "why_fa": "ampacity را به the lowest terminal temp سقف بزن؛ یک 90 cable روی یک 75 breaker یعنی همان عددِ 75"}, {"kw": "\"different temperature ratings in same raceway\"", "jump": "Rule 4-038", "why": "size all conductors on the LOWEST rating present; compute separately", "stars": 4, "why_fa": "همهٔ conductors را با the lowest rating موجود سایز کن و ampacity هرکدام را جداگانه حساب کن"}, {"kw": "\"continuous load\"", "jump": "Rule 8-104", "why": "conductor & breaker sized at 125% before ampacity check", "stars": 3, "why_fa": "conductor و breaker را قبل از بررسیِ ampacity، در 125% load سایز کن"}, {"kw": "\"neutral / identified conductor temperature rating\"", "jump": "Rule 4-016", "why": "neutral insulation not less than the ungrounded conductors", "stars": 3, "why_fa": "insulation rating یک neutral نباید از conductors فاز (ungrounded) کمتر باشد"}, {"kw": "\"neutral-supported / NS cable / overhead service\" copper", "jump": "Table 36B", "why": "Cu NS service/feeder cable, via Rule 4-004 5)", "stars": 3, "why_fa": "copper NS service/feeder cable، که Rule 4-004 5) تو را به آن می‌رساند"}, {"kw": "\"neutral-supported / NS / quadruplex\" aluminum", "jump": "Table 36A", "why": "Al NS overhead service cable", "stars": 3, "why_fa": "aluminum NS overhead service cable (همان quadruplex)"}, {"kw": "\"flexible cord / equipment wire / TEW / GTF / portable / elevator\"", "jump": "Table 12", "why": "cord & equipment-wire ampacity (cords 11A/11B, portable power 12A) via Rule 4-014/4-034", "stars": 3, "why_fa": "ampacity یک cord و equipment wire (cords از 11A/11B، portable power از 12A)، با ورود از Rule 4-014/4-034"}, {"kw": "\"underground / direct-buried / spaced\"", "jump": "Rule 4-004 1)d) + Diagrams D8/D10/D11", "why": "buried & spaced ampacity from Appendix D tables", "stars": 3, "why_fa": "ampacity حالت‌های buried و spaced را از tablesهای Appendix D دربیاور"}, {"kw": "\"bonding conductor counted for derating?\"", "jump": "Rule 4-004 6)", "why": "bonding/non current-carrying conductors are NOT counted", "stars": 4, "why_fa": "bonding conductors و هر non current-carrying conductor اصلاً شمرده نمی‌شوند"}, {"kw": "\"count-adjustment / derating factor for N conductors\"", "jump": "Table 5C", "why": "10 conductors -> 0.70; the standalone factor lookup", "stars": 4, "why_fa": "مثلاً 10 conductor ← 0.70؛ همان tableی که مستقیم the derate factor را به تو می‌دهد"}, {"kw": "\"phase conductor colours / 3-phase colour code\"", "jump": "Rule 4-036", "why": "A=red, B=black, C=blue", "stars": 2, "why_fa": "ترتیبِ colour سه‌فاز: A=red، B=black، C=blue"}, {"kw": "\"minimum conductor size for a given load\"", "jump": "Rule 4-004 + Tables 2/4", "why": "divide load by derate factors -> required table ampacity -> next size up", "stars": 4, "why_fa": "load را بر derate factors تقسیم کن ← the required table ampacity به‌دست می‌آید ← سایزِ بعدیِ بالاتر را بردار"}, {"kw": "\"voltage drop / smallest size by 3%-5% limit\"", "jump": "Rule 8-102 + Table D3", "why": "K ≤ (VD×1000)/(I·L·f); f=2 single-phase, √3 three-phase", "stars": 2, "why_fa": "برای voltage drop: K ≤ (VD×1000)/(I·L·f)؛ f=2 برای single-phase و √3 برای three-phase"}], "summary_fa": "کارِ این بخش ساده است اگر ترتیبش را بلد باشی: اول the correct ampacity table را بر اساس metal (copper/aluminum) و install method (free air یا raceway) انتخاب کن، بعد the base ampacity را در ضریبِ grouping (Table 5C) و ضریبِ ambient (Table 5A) ضرب کن، و در آخر همه را به the lowest terminal temperature سقف بزن. همین. وقتی the table grid توی ذهنت خودکار شد، این درس فقط «lookup و multiply» است و نمره‌اش را راحت می‌گیری.", "mustKnow_fa": ["table grid را مثل کفِ دستت بدان: free-air copper=T1، raceway copper=T2، free-air aluminum=T3، raceway aluminum=T4. حواست به حالتِ کمیابِ free-air aluminum (T3) باشد — آزمون دقیقاً همان‌جا کمین کرده.", "ضرایبِ grouping در Table 5C را حفظ کن: 4-6=0.80، 7-24=0.70، 25-42=0.60. فقط وقتی بیشتر از 3 تا current-carrying conductor کنار هم باشند فعال می‌شود، نه زودتر.", "Table 5A ambient فقط وقتی وارد بازی می‌شود که ambient بالای 30°C باشد؛ ضریب را از the insulation column (60/75/90) بردار و دما را همیشه رو به بالا، UP، گرد کن.", "اگر هر دو شرط برقرار بود، هر دو correction factor را پشت‌سرِ هم ضرب کن (grouping × ambient)؛ ترتیبشان هیچ فرقی نمی‌کند.", "فقط current-carrying conductors را بشمار: یک bonding/ground هیچ‌وقت شمرده نمی‌شود، و neutral یک مدار سه‌سیمهٔ balanced هم جزو شمارش نیست.", "Rule 4-038: اگر توی یک raceway دماهای مختلف بود، همه را با the lowest rating column بخوان.", "termination cap طبق Rule 4-006: یک 90°C cable روی یک 75°C breaker، به ampacity همان 75°C محدود می‌شود — نه بیشتر.", "NS overhead service: copper=Table 36B و aluminum=Table 36A. ضمناً min service conductor همان #10 Cu / #8 Al است (Rule 6-302)."], "traps_fa": ["خواندن از the 90°C column یک cable در حالی که terminal روی 75°C علامت خورده (Rule 4-006) — یادت نرود همیشه عددِ پایین‌تر حاکم است.", "رفتن سراغ Table 3 (free-air aluminum) برای یک copper conductor که فقط sheath آن aluminum است — table را فلزِ current-carrying تعیین می‌کند، نه sheath (S04-001).", "در یک raceway با دماهای mixed، فراموش کردنِ این‌که یک R90 conductor هم باید از the 75°C column خوانده شود وقتی یک 75°C conductor کنارش توی همان raceway است (Rule 4-038).", "derate کردنِ free-air conductors وقتی spacing ذکر نشده — در free air، grouping فقط وقتی اعمال می‌شود که spacing < 25% قطرِ بزرگ‌ترین cable باشد؛ اگر مسئله چیزی نگفته، اصلاً derate نکن.", "به حساب آوردنِ یک bonding یا یک balanced neutral به‌عنوان current-carrying، موقع اعمالِ Table 5C — این دو هیچ‌وقت شمرده نمی‌شوند.", "یادت رفتن که قبل از خواندنِ Table 5A، the ambient temp را رو به بالا، UP، به سطرِ بعدیِ فهرست‌شده گرد کنی.", "در سؤال‌های «minimum size»: اول load را بر derate factors تقسیم کن تا the required table ampacity به‌دست بیاید، بعد سایزِ استانداردِ بعدیِ بالاتر را بردار (S04-034)."], "method_fa": ["۱. the base table را انتخاب کن: metal (Cu/Al) + install method (free air در برابر raceway/cable) ← T1/T2/T3/T4 (یا 36A/B برای NS، T12 برای cord/equipment wire، Appendix D برای underground).", "۲. the base ampacity را از columnی بخوان که برابرِ conductor temp rating است؛ اگر توی یک raceway دماها mixed بود، با the lowest برو (Rule 4-038).", "۳. termination cap (Rule 4-006) را اعمال کن: اگر یک terminal دمای پایین‌تری علامت دارد، drop کن و از همان column بخوان.", "۴. grouping derate (Table 5C) را بزن اگر بیشتر از 3 تا current-carrying conductor داری؛ فقط power/lighting را بشمار.", "۵. ambient correction (Table 5A) را اعمال کن اگر ambient بالای 30°C است؛ دما را رو به بالا گرد کن و ضریب را از the insulation column بردار.", "۶. base × grouping × ambient را ضرب کن. برای «minimum size» برعکس عمل کن: اول the required load را بر factors تقسیم کن، بعد سایزِ استانداردِ بعدیِ بالاتر را بردار."], "mnemonic_fa": "این را یک‌بار حفظ کنی دیگر گم نمی‌شوی: Tables 1 و 2 = copper، 3 و 4 = aluminum؛ Tables 1 و 3 = free air، 2 و 4 = raceway. پس free-air copper = T1 و raceway aluminum = T4. برای correction factors هم: «5C = Count» (شمارشِ conductors برای grouping)، «5A = Air temp» (ambient)."}, {"section": 6, "name": "Services & Metering", "block": "B", "qcount": 12, "importance": 4, "summary": "Mostly direct lookups on overhead service heights/clearances, the service mast, and where service conductors/equipment may be located. Rule 6-112 and Table 32 dominate; memorize the heights and the 50 mm-concrete answer.", "keyTables": [{"ref": "Table 32", "stars": 4, "what": "Minimum overhead conductor clearances above ground/areas", "use": "read the row by what is below: pedestrians 3.5 m up to highways 5.5 m", "what_fa": "minimum overhead conductor clearances از زمین و از نواحیِ زیرش", "use_fa": "سطر را بر اساس آنچه زیرِ conductor قرار دارد انتخاب کن: از pedestrians 3.5 m تا highway 5.5 m"}], "keyRules": [{"ref": "Rule 6-112", "stars": 5, "what": "Service mast, heights, clearances, support/attachment", "note": "Mast metal, min 63 (2-1/2) rigid steel; point-of-attachment 3.5 m min to 9 m max; unguyed projection limit ~1.5 m; roof clearance 915 mm (600 mm over drip loop)", "what_fa": "service mast: heights، clearances، support/attachment", "note_fa": "mast باید metal باشد، حداقل rigid steel با سایزِ 63 (2-1/2)؛ point-of-attachment از 3.5 m (min) تا 9 m (max)؛ unguyed projection حدودِ 1.5 m؛ roof clearance برابرِ 915 mm (که روی drip loop به 600 mm کاهش می‌یابد)"}, {"ref": "Rule 6-300", "stars": 4, "what": "Consumer service conductors inside a building", "note": "Generally kept outside; if inside must be embedded in ≥50 mm of concrete or masonry (no overcurrent protection until the panel)", "what_fa": "consumer service conductors وقتی داخلِ building می‌روند", "note_fa": "اصل بر این است که outside بمانند؛ اما اگر مجبور شدی داخل ببری، باید در حداقل ≥50 mm concrete یا masonry مدفون (embedded) شوند — چون تا خودِ panel هیچ overcurrent protection روی این conductors نیست و آن لایهٔ concrete حکمِ محافظ را دارد"}, {"ref": "Rule 6-206", "stars": 4, "what": "Consumer service equipment location", "note": "As close as practicable to entry; NOT where headroom <2 m, not in bathroom/closet/coal bin, not where ambient normally >30°C", "what_fa": "محلِ مجازِ consumer service equipment", "note_fa": "تا حدِ عملی نزدیکِ نقطهٔ entry باشد؛ اما نه جایی که headroom < 2 m است، نه در bathroom/closet/coal bin، و نه جایی که ambient معمولاً > 30°C است"}, {"ref": "Rule 6-116", "stars": 3, "what": "Service-head / point-of-emergence dimensions", "note": "Conductor emergence 150-300 mm above and max 600 mm horizontally from the attachment", "what_fa": "ابعادِ service head / point-of-emergence هادی", "note_fa": "conductor باید 150-300 mm بالاتر از the attachment بیرون بزند و حداکثر 600 mm به‌صورت horizontal از آن فاصله داشته باشد"}, {"ref": "Rule 6-302", "stars": 3, "what": "Minimum consumer service conductor size", "note": "#10 Cu / #8 Al minimum — it is a MINIMUM, not 'house-sized'", "what_fa": "minimum consumer service conductor size", "note_fa": "minimum همان #10 Cu / #8 Al — حواست باشد این فقط یک minimum (کفِ مجاز) است، نه سایزِ معمولِ یک خانه"}, {"ref": "Rule 6-112 (clearance from openings)", "stars": 3, "what": "Clearance from windows/doors/porches", "note": "1.0 m clearance to sides and below (also Rule 6-116/12-310)", "what_fa": "clearance از windows/doors/porches", "note_fa": "باید 1.0 m clearance به طرفین و به پایین رعایت شود (به Rule 6-116/12-310 هم سر بزن)"}, {"ref": "Rule 6-102 / 6-104", "stars": 3, "what": "Number of supply vs consumer services", "note": "Max ONE supply service; max FOUR consumer services (unless a deviation)", "what_fa": "تعدادِ مجازِ supply service در برابر consumer service", "note_fa": "حداکثر یک supply service؛ و حداکثر چهار consumer service (مگر با یک deviation)"}, {"ref": "Rule 6-110", "stars": 2, "what": "Minimum service raceway size", "note": "Consumer service raceway not less than 21 (3/4) trade size", "what_fa": "minimum service raceway size", "note_fa": "consumer service raceway نباید از 21 (3/4) trade size کوچک‌تر باشد"}], "mustKnow": ["Point of attachment of overhead service conductors: minimum 3.5 m (pedestrian-only), maximum 9 m.", "Crossing a highway / alley / vehicle area: minimum 5.5 m (Table 32).", "Service mast: must be metal, minimum 63 (2-1/2) trade-size rigid steel conduit; unguyed projection limited to ~1.5 m.", "Min service conductor: #10 Cu / #8 Al (Rule 6-302) — a minimum, applies to small services.", "Service conductors inside a building must be embedded in ≥50 mm concrete/masonry (Rule 6-300) — the high-probability answer.", "Service equipment must not be where headroom <2 m (Rule 6-206).", "Drip loop: leave minimum 750 mm of extra conductor at the service head.", "Max ONE supply service; max FOUR consumer services (Rule 6-102/6-104).", "Clearance from porches/doors/windows = 1.0 m. Service raceway minimum 21 (3/4) trade size.", "Connection point: overhead = at the service head; underground = at the meter (no mid-run splice)."], "traps": ["Confusing the 9 m MAX point-of-attachment with the 5.5 m highway-crossing MINIMUM (different limits, different rows).", "Thinking #10 Cu / #8 Al is 'too small for a house' — it is the code MINIMUM, not the typical size.", "Choosing a steel-plate or rigid-pipe option for conductors inside a building — only the 50 mm-concrete embedment satisfies Rule 6-300.", "Using the 2 m × 2 m working-space figure for service equipment — service equipment needs 2 m HEADROOM (Rule 6-206), not the full working space.", "Mixing up service mast minimum (63 / 2-1/2) with service raceway minimum (21 / 3/4).", "Saying 'unlimited' consumer services — max is four unless a deviation is obtained."], "mnemonic": "Service heights climb 'people to pavement': 3.5 m pedestrians → 5.5 m highway → 9 m max attachment. Mast = '2½ and 63' (metal, big); raceway = '¾ and 21' (small). Inside a wall? '50 in concrete.'", "method": ["1. Identify the keyword: mast/attachment/clearance/inside-building/equipment-location/number-of-services.", "2. Height or clearance question -> Rule 6-112 + Table 32; read the row by what is below the conductors.", "3. 'Inside a building' -> Rule 6-300, answer = embedded in ≥50 mm concrete/masonry.", "4. 'Where can equipment go' -> Rule 6-206 (prohibited: <2 m headroom, bathroom, closet, >30°C ambient).", "5. Mast size/support -> Rule 6-112 (metal, 63 trade size, ~1.5 m unguyed). Min conductor -> Rule 6-302 (#10 Cu / #8 Al).", "6. Watch modifier words (minimum vs maximum) — the limit asked for flips the answer."], "examples": ["S06-004", "S06-005", "S06-006", "S06-007", "S06-010"], "keywords": [{"kw": "\"service mast / minimum rigid conduit size for mast\"", "jump": "Rule 6-112", "why": "metal, minimum 63 (2-1/2) trade-size rigid steel", "stars": 5, "why_fa": "metal، minimum یک rigid steel با trade-size 63 (2-1/2)"}, {"kw": "\"point of attachment height (max)\"", "jump": "Rule 6-112", "why": "maximum 9 m (utility bucket-truck reach)", "stars": 5, "why_fa": "maximum 9 m (تا دستِ bucket-truck شرکت برق به آن برسد)"}, {"kw": "\"crossing a highway / alley / vehicle area (min height)\"", "jump": "Table 32 + Rule 6-112", "why": "minimum 5.5 m over roadways/alleys", "stars": 5, "why_fa": "minimum 5.5 m بالای roadways/alleys"}, {"kw": "\"above pedestrians only (min height)\"", "jump": "Table 32 + Rule 6-112", "why": "minimum 3.5 m over pedestrian-only areas", "stars": 4, "why_fa": "minimum 3.5 m بالای نواحیِ pedestrian-only"}, {"kw": "\"conductors inside a building\"", "jump": "Rule 6-300", "why": "must be embedded in ≥50 mm concrete/masonry", "stars": 4, "why_fa": "باید در ≥50 mm concrete/masonry مدفون (embedded) شود (چون تا panel، overcurrent protection ندارد)"}, {"kw": "\"service equipment location / headroom\"", "jump": "Rule 6-206", "why": "not where headroom <2 m; not bathroom/closet/>30°C", "stars": 4, "why_fa": "نه جایی که headroom < 2 m است؛ نه bathroom/closet/ambient بالای > 30°C"}, {"kw": "\"minimum service conductor size\"", "jump": "Rule 6-302", "why": "#10 Cu / #8 Al minimum", "stars": 4, "why_fa": "minimum همان #10 Cu / #8 Al (یک minimum، نه سایزِ معمول)"}, {"kw": "\"clearance from porches / doors / windows\"", "jump": "Rule 6-116 / 6-112", "why": "1.0 m clearance to sides and below", "stars": 4, "why_fa": "clearance برابرِ 1.0 m به طرفین و به پایین"}, {"kw": "\"service-head point of emergence dimensions\"", "jump": "Rule 6-116", "why": "150-300 mm above, max 600 mm horizontal from attachment", "stars": 3, "why_fa": "150-300 mm بالاتر و maximum 600 mm horizontal از the attachment"}, {"kw": "\"number of supply / consumer services\"", "jump": "Rule 6-102 / 6-104", "why": "max ONE supply, max FOUR consumer (unless deviation)", "stars": 3, "why_fa": "maximum یک supply service، maximum چهار consumer (مگر با یک deviation)"}, {"kw": "\"minimum service raceway size\"", "jump": "Rule 6-110", "why": "not less than 21 (3/4) trade size", "stars": 3, "why_fa": "نباید از 21 (3/4) trade size کوچک‌تر باشد"}, {"kw": "\"drip loop / spare conductor at service head\"", "jump": "Rule 6-112 / 4-302", "why": "leave minimum 750 mm extra conductor", "stars": 3, "why_fa": "minimum 750 mm یک conductor اضافه برای the drip loop بگذار"}, {"kw": "\"roof clearance of service conductors\"", "jump": "Rule 6-112", "why": "915 mm above roof, reducible to 600 mm over the drip-loop area", "stars": 3, "why_fa": "915 mm بالای roof، که روی ناحیهٔ drip loop به 600 mm کاهش می‌یابد"}, {"kw": "\"unguyed mast projection / when is a guy wire needed\"", "jump": "Rule 6-112", "why": "projection above support beyond ~1.5 m requires guying", "stars": 2, "why_fa": "اگر projection بالای support از حدودِ 1.5 m بگذرد، باید guying بزنی"}, {"kw": "\"connection / splice point (overhead vs underground)\"", "jump": "Rule 6-112", "why": "overhead = at service head; underground = at the meter (no mid-run splice)", "stars": 2, "why_fa": "overhead = the service head؛ underground = the meter (بدونِ هیچ mid-run splice وسطِ مسیر)"}, {"kw": "\"meter base / metering location\"", "jump": "Section 6 + utility spec", "why": "metering equipment per Rule 6-200 series and utility requirements", "stars": 2, "why_fa": "محلِ metering equipment را سریِ Rule 6-200 به‌علاوهٔ utility requirements تعیین می‌کند"}, {"kw": "\"service / feeder demand load (interface to Sec 8)\"", "jump": "Rule 8-200 / 8-202", "why": "service size comes from the calculated demand, then size conductors in Sec 4", "stars": 2, "why_fa": "اول service size از the calculated demand load درمی‌آید، بعد conductors را در Section 4 سایز می‌کنی"}], "summary_fa": "بیشترِ سؤال‌های این بخش جستجوی مستقیم‌اند: ارتفاع و فاصلهٔ سرویسِ هوایی، دکلِ سرویس (mast)، و این‌که هادی‌ها و تجهیزاتِ سرویس کجا می‌توانند باشند. دو مرجع اینجا حرفِ اول را می‌زنند: Rule 6-112 و Table 32. اگر ارتفاع‌ها و آن پاسخِ معروفِ «50 mm بتن» را حفظ کنی، عملاً نمرهٔ این بخش را تضمین کرده‌ای.", "mustKnow_fa": ["point of attachment یک overhead service conductor: minimum 3.5 m (جایی که فقط pedestrian است) و maximum 9 m.", "عبور از highway / alley / محلِ ترددِ vehicle: minimum 5.5 m (Table 32).", "service mast باید metal باشد، minimum یک rigid steel conduit با سایزِ trade-size 63 (2-1/2)؛ unguyed projection حدودِ 1.5 m محدود است.", "min service conductor: #10 Cu / #8 Al (Rule 6-302) — یک minimum، مناسبِ سرویس‌های کوچک.", "service conductors داخلِ building باید در ≥50 mm concrete/masonry مدفون (embedded) شوند (Rule 6-300) — این همان پاسخی است که احتمالش بالاست.", "service equipment نباید جایی باشد که headroom < 2 m است (Rule 6-206).", "drip loop: minimum 750 mm یک conductor اضافه سرِ service head بگذار تا حلقهٔ آویزانِ آب‌ریز درست شود.", "حداکثر یک supply service؛ حداکثر چهار consumer service (Rule 6-102/6-104).", "clearance از porches/doors/windows = 1.0 m. و minimum service raceway = 21 (3/4) trade size.", "connection point: حالتِ overhead = the service head؛ حالتِ underground = the meter (بدونِ هیچ mid-run splice وسطِ مسیر)."], "traps_fa": ["قاطی کردنِ «maximum 9 m point-of-attachment» با «minimum 5.5 m highway-crossing» — این دو حدِ متفاوت‌اند و در rowهای متفاوتی هستند.", "این تصورِ غلط که #10 Cu / #8 Al «برای خانه خیلی کوچک است» — این code minimum است، نه سایزِ معمول؛ سؤال دنبالِ minimum است.", "انتخابِ گزینهٔ steel-plate یا rigid-pipe برای conductors داخلِ building — تنها چیزی که Rule 6-300 را برآورده می‌کند embedment در 50 mm concrete است.", "به‌کار بردنِ رقمِ working-space برابرِ 2 m × 2 m برای service equipment — service equipment به 2 m headroom نیاز دارد (Rule 6-206)، نه کلِ آن working space.", "قاطی کردنِ service mast minimum (63 / 2-1/2) با service raceway minimum (21 / 3/4) — mast بزرگ است، raceway کوچک.", "گفتنِ «unlimited» برای consumer services — سقفش four است، مگر یک deviation بگیری."], "mnemonic_fa": "service heights را با «از people تا pavement» به ذهن بسپار، از پایین به بالا: 3.5 m pedestrians ← 5.5 m highway ← 9 m max attachment. mast = «2½ و 63» (metal و بزرگ)؛ raceway = «¾ و 21» (کوچک). و اگر داخلِ یک wall رفت؟ «50 توی concrete».", "method_fa": ["۱. اول keyword سؤال را پیدا کن: mast / attachment / clearance / inside building / equipment location / number of services.", "۲. اگر سؤال از height یا clearance بود ← Rule 6-112 + Table 32؛ the row را بر اساس آنچه زیرِ conductors هست بخوان.", "۳. اگر «inside a building» بود ← Rule 6-300؛ پاسخ = embedded در ≥50 mm concrete/masonry.", "۴. اگر «equipment کجا می‌تواند باشد» بود ← Rule 6-206 (ممنوع: headroom < 2 m، bathroom، closet، ambient بالای > 30°C).", "۵. size یا support یک mast ← Rule 6-112 (metal، trade size 63، حدودِ 1.5 m unguyed). min conductor ← Rule 6-302 (#10 Cu / #8 Al).", "۶. حسابی مراقبِ modifier words باش (minimum در برابرِ maximum) — همان کلمه پاسخ را برعکس می‌کند."]}, {"section": 8, "name": "Loads & Demand", "block": "B", "qcount": 27, "importance": 5, "summary": "Calculate the CALCULATED (not connected) load for dwellings and non-dwellings, size ranges by service vs branch base, and apply the 2024 single-formula voltage drop method. Heavy math block that decides pass/fail.", "summary_fa": "ببین، کل ماجرای این بخش این است که باید «calculated load» (بارِ محاسبه‌شده) را به‌دست بیاوری، نه «connected load» — یعنی وات‌های روی nameplate لوازم را همین‌جوری با هم جمع نمی‌کنی. این کار را هم برای dwelling می‌کنی و هم non-dwelling. حواست به range هم باشد که base آن در محاسبهٔ service با محاسبهٔ branch circuit فرق دارد، و در آخر voltage drop را با همان فرمولِ واحدِ ۲۰۲۴ حساب می‌کنی. این بلوک پر از محاسبه است و راستش را بخواهی، قبولی و ردیِ خیلی‌ها همین‌جا تعیین می‌شود — پس رویش وقت بگذار.", "keyTables": [{"ref": "Table D3", "stars": 5, "what": "Voltage-drop K value (ohm/km) by size, material, temp, PF", "use": "2024 single formula VD=(K×I×L×F)/1000; defaults Cu, 75°C, PF=1", "what_fa": "این جدول مقدارِ voltage-drop K را بر حسب ohm/km به تو می‌دهد؛ K بستگی دارد به size هادی، material آن (copper یا aluminum)، temperature و power factor (PF).", "use_fa": "تنها کاربردش این است که K را برداری و توی فرمولِ واحدِ ۲۰۲۴ یعنی VD=(K×I×L×F)/1000 بگذاری. اگر سؤال چیزی نگفت، default را بگیر: copper (Cu)، 75°C و PF=1."}, {"ref": "Table 14", "stars": 4, "what": "Basic load W/m² by occupancy (store, theatre, etc.)", "use": "Non-dwelling basic area load under Rule 8-210", "what_fa": "basic load را بر حسب W/m² می‌دهد، آن هم بر اساسِ occupancy ساختمان (store، theatre و امثال این‌ها).", "use_fa": "هر وقت پای ساختمانِ non-dwelling وسط بود و خواستی basic area load را طبق Rule 8-210 حساب کنی، سراغِ این جدول می‌آیی."}, {"ref": "Table 2", "stars": 3, "what": "Ampacity, raceway Cu", "use": "Convert calculated demand (A) to conductor size at the terminal temp", "what_fa": "ampacity هادیِ copper را وقتی داخلِ raceway باشد می‌دهد.", "use_fa": "بعد از این‌که calculated demand را به آمپر (A) رساندی، با همین جدول آمپر را به conductor size تبدیل می‌کنی — یادت باشد در ستونِ terminal temperature بخوانی."}], "keyRules": [{"ref": "Rule 8-102", "stars": 5, "what": "Voltage drop limits + 2024 method", "note": "3% branch, 3% feeder, 5% supply-to-utilization total; 3%+3%≠5%", "what_fa": "این Rule 8-102 هم حدودِ voltage drop را تعیین می‌کند و هم همان روشِ تازهٔ 2024 را معرفی می‌کند.", "note_fa": "سه تا عدد را آویزهٔ گوشت کن: حداکثر 3% روی branch، 3% روی feeder، و در کل 5% از supply تا utilization. اما دامِ اصلی این‌جاست: 3%+3% مساویِ 5% نمی‌شود — یعنی نمی‌توانی هر دو را پر کنی، چون سقفِ total برابرِ 5% است."}, {"ref": "Rule 8-200", "stars": 5, "what": "Single-dwelling SERVICE/feeder demand", "note": "5000 W first 90 m² + 1000 W/extra 90 m²; range base 6 kW; min 100 A if ≥80 m²", "what_fa": "این Rule 8-200 قلبِ محاسبهٔ service/feeder demand برای یک single dwelling است.", "note_fa": "روشش این است: 5000 W برای 90 m² اول، بعد 1000 W به ازای هر 90 m² اضافه. range را با base برابرِ 6 kW می‌گیری. و اگر area برابرِ ≥80 m² باشد، service از 100 A کمتر نمی‌شود."}, {"ref": "Rule 8-210", "stars": 4, "what": "Non-dwelling demand (basic + actual loads)", "note": "Area × Table 14 W/m² per occupancy + connected loads at demand factors", "what_fa": "برای ساختمانِ non-dwelling است: basic load به‌علاوهٔ actual loads.", "note_fa": "منطقش ساده است: area را در W/m² از Table 14 (بر اساسِ occupancy) ضرب کن تا basic load دربیاید، بعد connected loads واقعی را با demand factor خودشان روی آن اضافه کن."}, {"ref": "Rule 8-300", "stars": 4, "what": "Range BRANCH-circuit demand", "note": "Dwelling: 8 kW base +40% over 12 kW; non-dwelling = 100% nameplate", "what_fa": "این یکی مخصوصِ branch circuit خودِ range است (نه service).", "note_fa": "برای dwelling، base برابرِ 8 kW است به‌علاوهٔ 40% هر چقدر که از 12 kW بالاتر زد. اما برای non-dwelling هیچ تخفیفی در کار نیست: 100% nameplate (پلاکِ مشخصات)."}, {"ref": "Rule 8-104", "stars": 4, "what": "Continuous load / 80% rule", "note": "Non-100% switch or breaker: continuous load ≤ 80% of rating", "what_fa": "همان قانونِ معروفِ 80% rule برای continuous load (بارِ پیوسته).", "note_fa": "اگر switch یا breaker تو از نوعِ 100% نیست (که اکثرشان نیستند)، continuous load نباید از 80% of rating دستگاه بیشتر شود. یا برعکس نگاهش کن: دستگاه را بزرگ‌تر بگیر، یعنی load تقسیم بر 0.80."}, {"ref": "Rule 8-106", "stars": 3, "what": "Non-coincident loads / interlock", "note": "Use only the LARGER of two loads that can't run together (e.g. heat vs AC)", "what_fa": "بحثِ non-coincident loads و interlock است.", "note_fa": "وقتی دو load به‌هیچ‌وجه با هم روشن نمی‌شوند (مثلِ heat و AC که interlock دارند)، فقط larger load را حساب می‌کنی، نه جمعِ هر دو را. منطقی هم هست: هیچ‌وقت قرار نیست هم‌زمان جریان بکشند."}, {"ref": "Rule 62-118", "stars": 3, "what": "Electric heating demand", "note": "Baseboard 100% first 10 kW + 75% remainder; electric furnace 100%; gas furnace not counted", "what_fa": "نحوهٔ حساب‌کردنِ electric heating demand این‌جاست.", "note_fa": "برای baseboard (رادیاتورِ برقی): 100% برای 10 kW اول و 75% برای remainder آن. electric furnace را کامل 100% بگیر. و حواست باشد gas furnace اصلاً جزوِ بارِ برقی حساب نمی‌شود — این را زیاد به‌عنوان دام می‌آورند."}, {"ref": "Rule 8-400", "stars": 2, "what": "EV / parking-space receptacle feeder demand", "note": "Controlled loading reduced; uncontrolled little/no reduction", "what_fa": "feeder demand برای receptacle خودروی برقی (EV) و parking space را تعیین می‌کند.", "note_fa": "نکتهٔ کلیدی این است: اگر loading از نوعِ controlled باشد، اجازه داری تخفیفِ خوبی بدهی؛ ولی اگر uncontrolled باشد، تقریباً هیچ تخفیفی نمی‌گیری."}], "mustKnow": ["VD limits: 3% branch / 3% feeder / 5% total supply-to-utilization (the #1 2021→2024 change)", "Range bases: SERVICE/feeder (8-200) = 6 kW; dwelling BRANCH (8-300) = 8 kW; both +40% over 12 kW", "Basic dwelling load: 5000 W first 90 m² + 1000 W each additional 90 m² (round UP partial increments)", "Min dwelling service: ≥80 m² → 24 000 W / 100 A; <80 m² → 14 400 W / 60 A (take larger)", "Other loads >1500 W with a range present: count at 25% (8-200 1)a)(vii))", "Heating (62-118): 100% first 10 kW + 75% remainder for baseboard", "Continuous (8-104): non-100% device carries load ≤ 80% of rating (or size device = load/0.80)", "Show window = 650 W/m along base; max 12 receptacles on a 15 A circuit", "Non-dwelling range = 100% nameplate (no demand reduction)", "VD factor F = 2 default; F = 1.73 (√3) only for 3-phase AC"], "mustKnow_fa": ["VD limits: 3% روی branch، 3% روی feeder، و 5% total از supply تا utilization — این مهم‌ترین تغییرِ 2021 به 2024 است، حتماً مالِ خودت کن.", "range base را قاطی نکن: در service/feeder (8-200) base برابرِ 6 kW است، در dwelling branch (8-300) base برابرِ 8 kW؛ هر دو هم 40% مازاد بر 12 kW می‌گیرند.", "basic dwelling load: 5000 W برای 90 m² اول، بعد 1000 W برای هر 90 m² اضافه — و هر increment ناقص را رو به بالا (round up) گرد کن، نه پایین.", "minimum dwelling service: اگر ≥80 m² شد یعنی 24 000 W که می‌شود 100 A؛ اگر <80 m² بود یعنی 14 400 W که می‌شود 60 A — هر کدام بزرگ‌تر شد همان را بردار.", "اگر range در خانه باشد، other loads بالای 1500 W را فقط با 25% حساب می‌کنی (طبق 8-200 1)a)(vii)).", "heating (62-118): برای baseboard، 100% برای 10 kW اول و 75% برای remainder — نه این‌که کلش را 100% بگیری.", "continuous load (8-104): دستگاهِ non-100% فقط تا 80% of rating خودش continuous load می‌کشد (یا size دستگاه = load تقسیم بر 0.80).", "show window (ویترینِ نمایش): 650 W per metre در طولِ base؛ و یادت باشد روی یک circuit برابرِ 15 A حداکثر 12 receptacle مجاز است.", "non-dwelling range = 100% nameplate، بدونِ هیچ demand reduction.", "VD factor یعنی F در فرمول، default برابرِ 2 است؛ مقدارِ 1.73 (یعنی √3) فقط مالِ 3-phase AC است، نه چیزِ دیگر."], "traps": ["Connected load vs CALCULATED load: appliance wattages are bait — use the 8-200 method, don't sum everything", "Range base confusion: 6 kW for service (8-200), 8 kW for dwelling branch (8-300) — different bases", "3% + 3% ≠ 5%: if branch uses full 3%, feeder may only use 2% to keep total ≤ 5%", "Non-dwelling range gets NO reduction (100%); reduction is dwelling-only", "Round partial 90 m² increments UP (e.g. 100 m² extra = 2 increments = 2000 W)", "Heating not at 100%: baseboard gets 100% first 10 kW + 75% remainder, not full kW", "3-phase wye service: divide by √3×line voltage when converting W to A; don't forget √3", "VD F-factor: F=2 for single-phase/DC; only true 3-phase AC uses 1.73"], "traps_fa": ["connected load را با calculated load قاطی نکن: وات‌های appliance عمداً گذاشته شده‌اند که گولت بزنند — تو از روشِ 8-200 برو جلو، همه را سرِ هم جمع نکن.", "range base همیشه گیج‌کننده است: 6 kW مالِ service (8-200) و 8 kW مالِ dwelling branch (8-300) — این دو base متفاوت‌اند، جابه‌جا نزن.", "3% + 3% مساویِ 5% نیست: اگر branch کلِ 3% را خورد، feeder فقط می‌تواند 2% بردارد تا total از 5% بالا نزند.", "non-dwelling range هیچ reduction نمی‌گیرد (100%)؛ آن reduction فقط dwelling-only است.", "increment های ناقصِ 90 m² را رو به بالا (round up) گرد کن (مثلاً 100 m² اضافه = 2 increment = 2000 W، نه یکی).", "heating هیچ‌وقت کامل 100% نیست: baseboard فقط 10 kW اول را 100% می‌گیرد و remainder را 75% — کلِ kW را نزن.", "در 3-phase wye service، موقعِ تبدیلِ W به A باید بر √3×line voltage تقسیم کنی — این √3 را خیلی‌ها فراموش می‌کنند.", "VD F-factor: برای single-phase و DC مقدارش 2 است؛ فقط جایی که واقعاً 3-phase AC داری از 1.73 استفاده می‌کنی."], "mnemonic": "VD = KILF/1000 (\"Kill over a thousand\"): K×I×L×F ÷ 1000.", "mnemonic_fa": "این فرمول را با «Kill over a thousand» حفظ کن: VD = KILF/1000، یعنی K×I×L×F تقسیم بر 1000. همین‌قدر ساده.", "method": ["Voltage drop (2024 single formula): VD=(K×I×L×F)/1000. VD=system V×allowed%; K from Table D3 (defaults Cu/75°C/PF1); L=one-way metres; F=2 (1.73 only 3-ph AC).", "Find max length: L ≤ (1000×VD)/(K×I×F). Find min size: K ≤ (1000×VD)/(I×L×F), then read Table D3 for a size with K ≤ that.", "Table D3 temp note: base 75°C; ×0.95 if 60°C, ×1.35 if 90°C. ELV/DC hint: ×0.86×K.", "Dwelling service (8-200): basic area load + range (6 kW base) + heating (62-118) + 25% of other >1500 W loads → ÷240 V → amps.", "Continuous 80% rule (8-104): device rating = continuous load ÷ 0.80, or max load = rating × 0.80."], "method_fa": ["voltage drop با فرمولِ واحدِ 2024: VD=(K×I×L×F)/1000. خودِ مقدارِ مجازِ VD را از system voltage × allowed % درمی‌آوری؛ K را از Table D3 بردار (default Cu/75°C/PF1)؛ L یعنی one-way length به متر است؛ و F=2 مگر این‌که 3-phase AC باشد که می‌شود 1.73.", "اگر دنبالِ max length هستی: L ≤ (1000×VD)/(K×I×F). اگر دنبالِ min size هستی: اول K ≤ (1000×VD)/(I×L×F) را حساب کن، بعد توی Table D3 یک size را بردار که K آن از این مقدار کمتر یا مساوی باشد.", "temperature note در Table D3: base برابرِ 75°C است؛ اگر 60°C بود ×0.95، اگر 90°C بود ×1.35. برای ELV/DC هم یادگارِ ذهنی‌ات این باشد: ×0.86×K.", "dwelling service (8-200): basic area load + range (با base برابرِ 6 kW) + heating (62-118) + 25% of other loads بالای 1500 W، بعد همه را تقسیم بر 240 V کن تا amps دربیاید.", "continuous 80% rule (8-104): device rating = continuous load ÷ 0.80، یا برعکس، max load = rating × 0.80."], "examples": ["S08-003", "S08-006", "S08-013", "S08-023", "S08-009", "S08-024"], "keywords": [{"kw": "\"voltage drop\"", "jump": "Rule 8-102 + Table D3", "why": "2024: ONE formula VD=(K×I×L×F)/1000; 3%/3%/5%", "stars": 5, "why_fa": "از 2024 فقط یک formula داریم: VD=(K×I×L×F)/1000، با همان سقف‌های 3%/3%/5%."}, {"kw": "\"single dwelling\" / \"calculate demand\"", "jump": "Rule 8-200", "why": "5000 W first 90 m² + 1000 W/extra; range base 6 kW", "stars": 5, "why_fa": "5000 W برای 90 m² اول + 1000 W برای هر increment اضافه؛ range base هم 6 kW."}, {"kw": "\"electric range\" / \"branch circuit\"", "jump": "Rule 8-300 1)a)", "why": "Dwelling branch base 8 kW +40% over 12 kW", "stars": 5, "why_fa": "dwelling branch base برابرِ 8 kW است + 40% هر چقدر از 12 kW بالاتر زد."}, {"kw": "\"basic load\" W/m² by occupancy", "jump": "Rule 8-210 + Table 14", "why": "Non-dwelling: area × occupancy W/m²", "stars": 4, "why_fa": "ساختمانِ non-dwelling: area × مقدارِ W/m² همان occupancy."}, {"kw": "\"continuous load\" / 80% switch or breaker", "jump": "Rule 8-104", "why": "Non-100% device: load ≤ 80% of rating", "stars": 4, "why_fa": "دستگاهِ non-100%: continuous load نباید از 80% of rating بالا برود."}, {"kw": "\"electric heating\" / baseboard / furnace demand", "jump": "Rule 8-200 1)a)(v) + Rule 62-118", "why": "100% first 10 kW + 75% remainder; gas furnace not counted", "stars": 4, "why_fa": "100% برای 10 kW اول + 75% remainder؛ و یادت باشد gas furnace اصلاً حساب نمی‌شود."}, {"kw": "\"minimum service\" for dwelling area", "jump": "Rule 8-200 1)b)", "why": "≥80 m² → 100 A; <80 m² → 60 A", "stars": 4, "why_fa": "اگر ≥80 m² بود می‌شود 100 A؛ اگر <80 m² بود می‌شود 60 A — یعنی minimum service."}, {"kw": "\"show window\"", "jump": "Rule 8-200 1)b)", "why": "650 W per metre along base", "stars": 3, "why_fa": "show window: 650 W per metre در طولِ base."}, {"kw": "\"apartment\" / multiple dwelling", "jump": "Rule 8-202", "why": "Multi-dwelling demand with reductions per # of units", "stars": 3, "why_fa": "multi-dwelling demand، با reduction بر اساسِ تعدادِ unit ها."}, {"kw": "\"non-coincident\" / two loads not together / heat vs AC interlock", "jump": "Rule 8-106 3)", "why": "Use only the LARGER load", "stars": 3, "why_fa": "فقط larger load را حساب کن، چون هر دو با هم روشن نمی‌شوند."}, {"kw": "\"range in commercial/industrial\" / non-dwelling range", "jump": "Rule 8-300 2)", "why": "100% nameplate, no reduction", "stars": 3, "why_fa": "100% nameplate، بدونِ هیچ reduction."}, {"kw": "\"how many receptacles\" on a circuit", "jump": "Rule 8-304 / 26-712", "why": "Max 12 outlets on a 15 A circuit", "stars": 3, "why_fa": "روی یک circuit برابرِ 15 A حداکثر 12 outlet (receptacle) مجاز است."}, {"kw": "\"parking spaces\" / \"EV charger\" load", "jump": "Rule 8-400", "why": "Controlled = reduced; uncontrolled = little reduction", "stars": 2, "why_fa": "controlled یعنی reduction خوب؛ uncontrolled یعنی تقریباً بدونِ reduction."}, {"kw": "\"extra-low voltage\" VD / emergency lamp distance", "jump": "Rule 8-102 + Table D3", "why": "Same formula; ELV hint ×0.86×K; F=2 for DC", "stars": 2, "why_fa": "همان formula همیشگی؛ برای ELV همان ×0.86×K؛ و چون DC است F=2."}, {"kw": "\"two occupancies\" in one building", "jump": "Rule 8-210 + Table 14", "why": "Compute each area at its own W/m², then add", "stars": 2, "why_fa": "هر occupancy را با W/m² مخصوصِ خودش جدا حساب کن، بعد رویِ هم جمع‌شان کن."}]}, {"section": 10, "name": "Grounding & Bonding", "block": "B", "qcount": 14, "importance": 4, "summary": "Distinguish grounding (electrode conductor, Table 43, keyed to service-conductor ampacity) from bonding (Table 16, by overcurrent device). Know field-assembled electrode geometry, equipotential bonding sizes, and the bare-conductor-in-raceway limits.", "summary_fa": "اول از همه باید فرقِ grounding (اتصال به زمین) را با bonding (پیوستگی) حسابی توی ذهنت جا بیندازی، چون امتحان دقیقاً همین‌جا گیرت می‌اندازد. grounding electrode conductor را از Table 43 می‌گیری که وابسته به ampacity of the service conductor است؛ ولی bonding conductor را از Table 16 برمی‌داری که به overcurrent device بستگی دارد. بعد هم باید geometry الکترودِ field-assembled، اندازه‌های equipotential bonding و محدودیتِ bare conductor داخلِ raceway را بلد باشی. زیاد نیست، ولی همه‌اش جزئیاتِ ریز است.", "keyTables": [{"ref": "Table 43", "stars": 5, "what": "Grounding (electrode) conductor size", "use": "Keyed to AMPACITY of largest service conductor — NOT breaker, NOT load", "what_fa": "اندازهٔ grounding electrode conductor (هادیِ اتصال‌زمینِ الکترود) از این Table 43 درمی‌آید.", "use_fa": "نکتهٔ طلایی این است: این جدول بر اساسِ ampacity of the largest service conductor انتخاب می‌شود — نه breaker rating، نه load current. این را اگر سرِ امتحان قاطی کنی، باخته‌ای."}, {"ref": "Table 16", "stars": 4, "what": "Bonding conductor / jumper size", "use": "Sized by ampacity OR rating of the overcurrent device ahead of it", "what_fa": "اندازهٔ bonding conductor یا bonding jumper را این Table 16 می‌دهد.", "use_fa": "این یکی برعکسِ Table 43 است: بر اساسِ ampacity یا rating of the overcurrent device که جلویش نشسته اندازه‌گیری می‌شود."}, {"ref": "Table 2", "stars": 3, "what": "Ampacity, raceway Cu", "use": "Get service-conductor ampacity (at its temp column) before entering Table 43", "what_fa": "ampacity هادیِ copper داخلِ raceway را می‌دهد.", "use_fa": "قبل از این‌که سراغِ Table 43 بروی، اول باید service-conductor ampacity را از همین‌جا دربیاوری — آن هم در ستونِ temperature درستِ خودش."}], "keyRules": [{"ref": "Rule 10-114", "stars": 5, "what": "Sizing grounding conductor to electrode", "note": "Table 43 by service-conductor ampacity; to a MANUFACTURED electrode need not exceed #6 Cu", "what_fa": "این Rule 10-114 می‌گوید grounding conductor تا electrode را چطور اندازه بزنی.", "note_fa": "از Table 43 برو، بر اساسِ service-conductor ampacity. ولی یک استثنای مهم: اگر داری به یک manufactured electrode (مثلِ rod یا plate) وصل می‌شوی، لازم نیست از #6 Cu بزرگ‌تر بگیری — هرچه جدول هم بگوید، سقفت #6 است."}, {"ref": "Rule 10-102", "stars": 4, "what": "Field-assembled (concrete-encased) electrode", "note": "≥6 m bare Cu (≥#4), in bottom 50 mm of footing, ≥600 mm below grade", "what_fa": "مشخصاتِ field-assembled electrode (concrete-encased، محصور در بتن) را تعیین می‌کند.", "note_fa": "اعدادش را حفظ کن: حداقل 6 m bare Cu که از #4 کوچک‌تر نباشد، داخلِ 50 mm پایینیِ footing، و حداقل 600 mm below grade (زیرِ سطحِ زمین)."}, {"ref": "Rule 10-406", "stars": 4, "what": "Equipotential bonding", "note": "Min #6 Cu / #4 Al (pools, raised floors, etc.)", "what_fa": "equipotential bonding (باندینگِ هم‌پتانسیل) را پوشش می‌دهد.", "note_fa": "minimum آن #6 Cu یا #4 Al است؛ هر جا پای pool، raised floor و امثالش وسط باشد همین حداقل را به یاد بیاور."}, {"ref": "Rule 10-104", "stars": 3, "what": "Electrode spacing", "note": "Two+ rod/plate electrodes spaced ≥ 3 m apart", "what_fa": "electrode spacing (فاصلهٔ بینِ الکترودها) را مشخص می‌کند.", "note_fa": "اگر دو یا چند rod/plate electrode داری، باید دستِ‌کم 3 m از هم فاصله داشته باشند، وگرنه عملاً مثلِ یک electrode عمل می‌کنند."}, {"ref": "Rule 10-806", "stars": 3, "what": "Bare grounding conductor in raceway", "note": "Bare system grounding conductor in raceway only where run ≤ 15 m", "what_fa": "اجازهٔ عبورِ bare grounding conductor داخلِ raceway را تعیین می‌کند.", "note_fa": "bare system grounding conductor را فقط وقتی می‌توانی داخلِ raceway ببری که run از 15 m بیشتر نشود — همین یک شرط."}, {"ref": "Rule 10-614 / 10-616", "stars": 3, "what": "Bonding conductor sizing", "note": "Size from OCPD rating via Table 16 (e.g. 40 A → #10 Cu)", "what_fa": "نحوهٔ bonding conductor sizing این‌جاست.", "note_fa": "rating دستگاهِ حفاظت (OCPD) را بردار و با Table 16 سایز را دربیاور (مثلاً 40 A می‌شود #10 Cu)."}], "mustKnow": ["Grounding ELECTRODE conductor = Table 43, keyed to SERVICE-CONDUCTOR AMPACITY (4/0 Cu @75°C=230 A → size 2)", "BONDING conductor/jumper = Table 16, by ampacity OR overcurrent device rating", "To a MANUFACTURED (rod/plate) electrode the grounding conductor need not exceed #6 Cu (10-114)", "Field-assembled electrode: ≥6 m of bare Cu, not smaller than #4, bottom 50 mm of footing, ≥600 mm below grade", "Electrode spacing: ≥ 3 m between rod/plate electrodes", "Equipotential bonding (10-406): #6 Cu / #4 Al minimum", "Bare grounding conductor shares a raceway only if run ≤ 15 m (10-806)", "Bends limit in a run is 360° (four quarter-bends) per 12-940 — not a '180°' grounding limit", "Table 43 lowest band: ampacity ≤165 A → size 4; 166–200 A → size 3; then 2,1,1/0...", "Raised metal floor (Section 84) bonded as equipotential: #8 Cu / #6 Al"], "mustKnow_fa": ["grounding electrode conductor = Table 43، و کلیدش service-conductor ampacity است (مثلاً 4/0 Cu در 75°C می‌شود 230 A که از جدول size 2 درمی‌آید).", "bonding conductor یا bonding jumper = Table 16، بر اساسِ ampacity یا overcurrent device rating — این دو را با هم اشتباه نگیر.", "وقتی به manufactured electrode (rod/plate) می‌روی، grounding conductor لازم نیست از #6 Cu بزرگ‌تر باشد (10-114) — این سقف یادت نرود.", "field-assembled electrode: حداقل 6 m bare Cu، نه کوچک‌تر از #4، داخلِ 50 mm پایینیِ footing، و حداقل 600 mm below grade.", "electrode spacing: بینِ rod/plate electrode ها حداقل 3 m.", "equipotential bonding (10-406): حداقل #6 Cu یا #4 Al.", "bare grounding conductor فقط وقتی با بقیه توی یک raceway می‌رود که run ≤ 15 m باشد (10-806).", "bends limit در یک run برابرِ 360° است (یعنی four quarter-bends) طبق 12-940 — این را با یک حدِ خیالیِ «180°» برای grounding قاطی نکن.", "پایین‌ترین band در Table 43: ampacity برابرِ ≤165 A می‌شود size 4؛ 166–200 A می‌شود size 3؛ بعد به ترتیب 2، 1، 1/0 و بالاتر.", "raised metal floor (Section 84) را به‌صورتِ equipotential باند می‌کنی: #8 Cu یا #6 Al."], "traps": ["Table 43 vs Table 16: ELECTRODE conductor uses ampacity ONLY (Table 43); BONDING uses ampacity OR device (Table 16)", "Table 43 is keyed to SERVICE-CONDUCTOR AMPACITY, never the breaker rating or the load current", "Manufactured electrode cap: grounding conductor need not exceed #6 Cu — don't oversize from Table 43", "Bare-in-raceway limit is 15 m by length (10-806); separately bends ≤ 360° (12-940) — add offsets/bends", "Equipotential bonding direction: Al is one size LARGER than Cu (#4 Al ≡ #6 Cu)", "Read the temp column: a 60°C cable (TW) ampacity from Table 2's 60°C column before Table 43", "PV DC grounding is Section 64, not Section 10 (those questions are mis-filed)"], "traps_fa": ["Table 43 در برابرِ Table 16: electrode conductor فقط ampacity می‌خواهد (Table 43)؛ ولی bonding یا ampacity یا overcurrent device را می‌خواهد (Table 16) — این تفاوت همان جایی است که اکثراً می‌لغزند.", "Table 43 همیشه با service-conductor ampacity کار می‌کند، هرگز با breaker rating یا load current — حتی اگر سؤال عمداً عددِ breaker را جلویت بگذارد.", "سقفِ manufactured electrode: grounding conductor لازم نیست از #6 Cu بزرگ‌تر باشد — از Table 43 بیخود بزرگ‌تر برندار.", "حدِ bare-in-raceway بر اساسِ length است یعنی 15 m (10-806)؛ جدا از آن، bends هم باید ≤ 360° باشند (12-940) — offsets و bends را با هم جمع کن.", "جهتِ equipotential bonding را برعکس نزن: aluminum یک size بزرگ‌تر از copper است (#4 Al معادلِ #6 Cu).", "temperature column را با دقت بخوان: ampacity کابلِ 60°C (مثلِ TW) را باید از ستونِ 60°C در Table 2 برداری، بعد بروی سراغِ Table 43.", "PV DC grounding مربوط به Section 64 است، نه Section 10 — اگر چنین سؤالی دیدی، بدان جای دیگری دنبالِ جوابش بگرد."], "mnemonic": "\"43 to the EARTH, 16 to the BOX\": Table 43 = electrode/ground; Table 16 = bonding.", "mnemonic_fa": "این جمله را حفظ کن: «43 to the EARTH، 16 to the BOX» — یعنی Table 43 برای electrode/ground، و Table 16 برای bonding. دیگر هیچ‌وقت قاطی‌شان نمی‌کنی.", "method": ["Grounding electrode conductor: get the LARGEST service conductor's ampacity from Table 2 (correct temp column) → enter Table 43 → read size. Cap at #6 Cu if going to a manufactured electrode (10-114).", "Bonding conductor: take the OCPD ampere rating → Table 16 → minimum Cu/Al bond (10-614/10-616).", "Field-assembled electrode check: ≥6 m bare Cu ≥#4, bottom 50 mm of footing, ≥600 mm below grade, electrodes ≥3 m apart.", "Bare conductor in raceway: confirm run ≤ 15 m (10-806) and total bends ≤ 360° (12-940)."], "method_fa": ["grounding electrode conductor: اول ampacity of the largest service conductor را از Table 2 بگیر (در ستونِ temperature درست)، بعد با همان وارد Table 43 شو و size را بخوان. اگر مقصدت manufactured electrode است، cap را #6 Cu بگذار (10-114).", "bonding conductor: ampere rating دستگاهِ حفاظت (OCPD) را بردار، با Table 16 برو، و minimum bond از نوعِ Cu/Al را دربیاور (10-614/10-616).", "چک‌لیستِ field-assembled electrode: حداقل 6 m bare Cu برابرِ ≥#4، در 50 mm پایینیِ footing، حداقل 600 mm below grade، و electrode ها با فاصلهٔ ≥3 m از هم.", "bare conductor در raceway: مطمئن شو run ≤ 15 m است (10-806) و total bends ≤ 360° (12-940)."], "examples": ["S10-007", "S10-008", "S10-009", "S10-006", "S10-004", "S10-014"], "keywords": [{"kw": "\"grounding electrode conductor\" / size of grounding conductor", "jump": "Rule 10-114 + Table 43", "why": "Keyed to service-conductor AMPACITY (not breaker)", "stars": 5, "why_fa": "کلیدش service-conductor ampacity است، نه breaker rating."}, {"kw": "\"bonding conductor\" / bonding jumper", "jump": "Rule 10-614/10-616 + Table 16", "why": "Sized by ampacity OR overcurrent device rating", "stars": 5, "why_fa": "بر اساسِ ampacity یا overcurrent device rating اندازه می‌شود."}, {"kw": "\"field-assembled\" / concrete-encased electrode", "jump": "Rule 10-102", "why": "≥6 m bare Cu ≥#4, bottom 50 mm of footing, ≥600 mm deep", "stars": 4, "why_fa": "حداقل 6 m bare Cu برابرِ ≥#4، 50 mm پایینیِ footing، و حداقل 600 mm below grade."}, {"kw": "\"equipotential bonding\" (pool, raised floor, pipe)", "jump": "Rule 10-406", "why": "#6 Cu / #4 Al minimum", "stars": 4, "why_fa": "minimum برابرِ #6 Cu یا #4 Al."}, {"kw": "\"manufactured\" / rod / plate electrode conductor", "jump": "Rule 10-114", "why": "Need not exceed #6 Cu", "stars": 4, "why_fa": "لازم نیست از #6 Cu بزرگ‌تر باشد — همین‌جا cap را بزن."}, {"kw": "\"electrode spacing\" / two electrodes apart", "jump": "Rule 10-104", "why": "≥ 3 m apart", "stars": 3, "why_fa": "electrode spacing با فاصلهٔ حداقل 3 m از هم."}, {"kw": "\"bare grounding conductor\" in raceway / conduit length", "jump": "Rule 10-806", "why": "Bare allowed only if run ≤ 15 m", "stars": 3, "why_fa": "bare conductor فقط وقتی مجاز است که run ≤ 15 m باشد."}, {"kw": "\"grounded vs bonding\" / definitions", "jump": "Rule 10-114 / Section 0", "why": "Bonding = low-impedance path for non-current-carrying metal; memorize the sentence", "stars": 3, "why_fa": "bonding یعنی low-impedance path برای non-current-carrying metal؛ خودِ این جمله را عیناً حفظ کن."}, {"kw": "\"raised floor\" / computer room bonding", "jump": "Section 84 + Rule 10-406", "why": "Equipotential: #8 Cu / #6 Al", "stars": 2, "why_fa": "equipotential bonding: #8 Cu یا #6 Al."}, {"kw": "\"bonding jumper\" for a 40 A device", "jump": "Table 16", "why": "OCPD rating → #10 Cu", "stars": 2, "why_fa": "OCPD rating برابرِ 40 A می‌شود #10 Cu."}, {"kw": "\"PV DC\" grounding / two-wire system", "jump": "Section 64 (not Section 10)", "why": "Functionally-grounded/ungrounded arrays permitted in 2024", "stars": 2, "why_fa": "در 2024 آرایه‌های functionally-grounded یا ungrounded مجازند — و این بحث در Section 64 است نه این‌جا."}, {"kw": "\"service-conductor ampacity\" → electrode size", "jump": "Table 43", "why": "≤165 A → size 4; 166–200 A → size 3; then 2,1,1/0", "stars": 3, "why_fa": "service-conductor ampacity برابرِ ≤165 A می‌شود size 4؛ 166–200 A می‌شود size 3؛ بعد 2، 1، 1/0."}]}, {"section": 12, "name": "Wiring Methods", "block": "C", "qcount": 74, "importance": 5, "summary": "The single biggest source of exam questions (Block C) — conduit fill, box/pull-box fill, cover depths, bend radius and cable rules dominate. Most of these are pure table lookups, so speed and the right table choice decide pass/fail here.", "summary_fa": "ببین، پرسؤال‌ترین قسمتِ کلِ آزمون همین Block C است. هرچه دیدی دربارهٔ conduit fill (پرشدنِ لوله)، box fill و pull-box، cover (عمقِ دفن)، bend radius (شعاعِ خم) و قوانینِ cable، از همین‌جا می‌آید. نکتهٔ کلیدی این است که تقریباً همه‌اش table lookup است؛ یعنی اگر سریع باشی و table درست را بشناسی، همین بخش قبولی‌ات را تضمین می‌کند — برعکس، اگر اینجا لنگ بزنی، می‌بازی. پس روی همین تمرکز کن.", "keyTables": [{"ref": "Table 10", "stars": 5, "what": "Conductor cross-sectional area (insulation incl.)", "what_fa": "cross-sectional area (سطح مقطع) هر conductor همراه با insulation اش (Table 10)", "use": "Feeds every conduit/raceway/gutter fill calc — sum areas here", "use_fa": "این پایهٔ هر محاسبهٔ conduit/raceway/gutter fill است؛ area تک‌تکِ conductorها را از همین‌جا بردار و با هم جمع بزن."}, {"ref": "Table 6", "stars": 5, "what": "Max conductors / conduit dimensions for fill", "what_fa": "بیشترین تعدادِ conductor و ابعادِ conduit برای fill (Table 6)", "use": "Pick smallest conduit whose allowable area ≥ total", "use_fa": "کوچک‌ترین conduit ای را بردار که allowable area اش از مجموعِ conductorهایت کمتر نباشد — هرچه کوچک‌تر و درست‌تر، بهتر."}, {"ref": "Table 8", "stars": 5, "what": "Maximum raceway fill %", "what_fa": "بیشترین درصدِ مجازِ raceway fill (Table 8)", "use": "1→53%, 2→31%, 3+→40% (not-lead-sheathed top row)", "use_fa": "این fill percentages را حفظ کن: one conductor 53%، two 31%، three+ 40% (ردیفِ بالای not-lead-sheathed)."}, {"ref": "Table 9", "stars": 4, "what": "Conduit % cross-section areas by trade size", "what_fa": "درصدِ cross-section area لوله به تفکیکِ trade size (Table 9)", "use": "Used with Table 6/8 to land the conduit size and for pull-box math", "use_fa": "دستِ کمکِ Table 6/8 است؛ هم برای رسیدن به conduit size و هم برای حسابِ pull-box ازش استفاده می‌کنی."}, {"ref": "Table 23", "stars": 5, "what": "Max conductors permitted in standard boxes", "what_fa": "بیشترین conductor مجاز در box های استاندارد (Table 23)", "use": "Quick box-fill lookup by conductor size", "use_fa": "میان‌برِ box fill است؛ conductor size را می‌بینی و یک‌راست تعداد را می‌خوانی، بدون حساب‌وکتاب."}, {"ref": "Table 22", "stars": 4, "what": "mL volume allowance per conductor by size", "what_fa": "volume مجاز برحسب mL برای هر conductor به تفکیکِ size (Table 22)", "use": "Box-fill calc: multiply mL/conductor × equivalents", "use_fa": "وقتی می‌خواهی box fill را دقیق حساب کنی: mL هر conductor را در تعدادِ equivalent ضرب کن."}, {"ref": "Table 53", "stars": 5, "what": "Minimum underground cover depths", "what_fa": "حداقل cover (عمقِ دفن) در underground (Table 53)", "use": "By voltage, protection, vehicular vs non-vehicular; -150 mm with mech. protection", "use_fa": "ورود به table با سه چیز: voltage، اینکه protection داری یا نه، و vehicular است یا non-vehicular. یادت باشد mechanical protection مقدارِ 150 mm از cover کم می‌کند."}, {"ref": "Table 7", "stars": 4, "what": "Minimum bend radius by trade size", "what_fa": "حداقل bend radius (شعاعِ خم) به تفکیکِ trade size (Table 7)", "use": "Radius set by CONDUIT size, not the conductor", "use_fa": "حواست باشد: bend radius را خودِ conduit size تعیین می‌کند، نه conductor داخلش — اینجا اشتباه نکن."}, {"ref": "Table 21", "stars": 3, "what": "Vertical-raceway conductor support spacing", "what_fa": "فاصلهٔ support های conductor در raceway عمودی (Table 21)", "use": "By conductor size — bigger/heavier = shorter spacing", "use_fa": "بر اساس conductor size است؛ منطقش ساده است — هرچه conductor بزرگ‌تر و سنگین‌تر، فاصلهٔ supportها کوتاه‌تر."}, {"ref": "Table 19 / Table D1", "stars": 3, "what": "Cable type by condition & voltage rating", "what_fa": "انتخابِ cable type بر اساس condition محیط و voltage rating (Table 19 / Table D1)", "use": "NMD90=300V, AC90≤2000V, TECK90≤5000V; dry/damp/wet selection", "use_fa": "این سه را به خاطر بسپار: NMD90 تا 300V، AC90 تا 2000V، TECK90 تا 5000V؛ و cable را با محیطِ dry/damp/wet (خشک/نم‌دار/تر) جور کن."}, {"ref": "Table 38", "stars": 2, "what": "Conduit thermal expansion coefficient", "what_fa": "thermal expansion coefficient لوله (Table 38)", "use": "Expansion = coeff × length(m) × ΔT for RPVC runs", "use_fa": "برای مسیرهای RPVC: مقدارِ expansion = coeff × length (m) × ΔT — همین فرمولِ ساده کافی است."}], "keyRules": [{"ref": "Rule 12-910", "stars": 5, "what": "Conductors per conduit/raceway (fill)", "what_fa": "تعدادِ conductor مجاز در هر conduit/raceway، یعنی همان conduit fill (Rule 12-910)", "note": "Use with Tables 6/8/9/10; the fill engine", "note_fa": "این قلبِ محاسبهٔ fill است؛ همیشه دستِ‌درستِ Tables 6/8/9/10 با آن می‌رود."}, {"ref": "Rule 12-3036", "stars": 5, "what": "Pull/junction box sizing", "what_fa": "تعیینِ اندازهٔ pull box و junction box (Rule 12-3036)", "note": "Straight pull = 8× largest raceway; angle/U = 6× largest + sum of others on that wall", "note_fa": "دو حالت را جدا کن: straight pull = 8 برابرِ بزرگ‌ترین raceway؛ angle یا U = 6 برابرِ بزرگ‌ترین + مجموعِ بقیهٔ راه‌ها روی همان wall."}, {"ref": "Rule 12-3034", "stars": 4, "what": "Box fill / minimum box volume", "what_fa": "box fill و حداقل box volume لازم (Rule 12-3034)", "note": "Device = 1 conductor of largest size; bond adds NO separate volume", "note_fa": "دو نکتهٔ طلایی: هر device را یک conductor هم‌اندازهٔ بزرگ‌ترین حساب کن، و bond conductor اینجا volume جداگانه نمی‌گیرد."}, {"ref": "Rule 12-012", "stars": 5, "what": "Underground installation / minimum cover", "what_fa": "underground installation و حداقل cover (Rule 12-012)", "note": "Pairs with Table 53; mech. protection reduces cover 150 mm", "note_fa": "همیشه با Table 53 جفت می‌شود؛ یادت باشد mechanical protection مقدارِ 150 mm از cover کم می‌کند."}, {"ref": "Rule 12-516", "stars": 4, "what": "Cable through studs/joists — 32 mm from edge", "what_fa": "عبورِ cable از داخلِ studs/joists — 32 mm از edge (Rule 12-516)", "note": "Else steel protector plate (Fig 12-30)", "note_fa": "اگر آن 32 mm را نداری، باید steel protector plate بگذاری (Fig 12-30) تا میخ به cable آسیب نزند."}, {"ref": "Rule 12-940", "stars": 4, "what": "Max bends between pull points", "what_fa": "بیشترین number of bends مجاز بینِ دو pull point (Rule 12-940)", "note": "Equivalent of four 90° bends = 360° total", "note_fa": "سقفت equivalent of four 90° bends است، یعنی رویِ‌هم 360° — بیشتر شد، باید pull box بگذاری."}, {"ref": "Rule 12-552", "stars": 4, "what": "NMD90 / non-metallic sheathed cable max voltage", "what_fa": "بیشترین voltage برای NMD90 / non-metallic sheathed cable (Rule 12-552)", "note": "300 V (with Table D1)", "note_fa": "سقفش 300 V است (با Table D1) — نه 600 V، اینجا گول نخور."}, {"ref": "Rule 12-510 / 12-520", "stars": 3, "what": "NMSC clearances & support spacing", "what_fa": "clearance ها و support spacing برای NMSC (Rule 12-510 / 12-520)", "note": "25 mm from heat pipe, 50 mm from chimney; within 300 mm of box then ≤1.5 m", "note_fa": "از heat pipe مقدارِ 25 mm و از chimney مقدارِ 50 mm فاصله بده؛ اولین support را تا 300 mm از box بزن و بعد هر ≤1.5 m یکی."}, {"ref": "Rule 12-108", "stars": 3, "what": "Parallel conductors", "what_fa": "parallel conductors (هادی‌های موازی) (Rule 12-108)", "note": "Permitted only for #1/0 AWG and larger", "note_fa": "parallel بستن فقط از #1/0 AWG به بالا اجازه دارد، نه کوچک‌تر."}, {"ref": "Rule 12-118", "stars": 3, "what": "Terminations", "what_fa": "termination ها و اتصالاتِ انتهایی (Rule 12-118)", "note": ">#10 needs a lug; #10 solid max under a binding screw; Belleville washer for Al lugs", "note_fa": "بزرگ‌تر از #10 حتماً lug می‌خواهد؛ #10 solid نهایتِ چیزی است که زیرِ binding screw می‌رود؛ و برای aluminum lug واشرِ Belleville لازم است."}, {"ref": "Rule 12-2100", "stars": 2, "what": "Wireway / auxiliary-gutter fill", "what_fa": "wireway و auxiliary-gutter fill (Rule 12-2100)", "note": "Max 20% area, max 30 current-carrying conductors", "note_fa": "دو سقف را با هم نگه دار: حداکثر 20% از area، و حداکثر 30 current-carrying conductor."}], "mustKnow": ["Fill %: 1 conductor→53%, 2→31%, 3 or more→40% (Table 8). Conduit-fill engine = Table 10 (areas) + Table 8 (fill %) + Table 6/9 (conduit size); bonding conductor IS counted in conduit fill.", "Box fill (CEC ≠ NEC): a device (receptacle/switch) counts as ONE conductor of the largest size; the bonding/ground conductor adds NO separate volume; wire connectors are NOT each counted like in the NEC.", "Pull boxes (12-3036): straight pull = 8× largest raceway trade size; angle or U pull = 6× largest + sum of the other raceways entering the same wall.", "Max bends between pull points = 4 × 90° = 360° (12-940). Bend radius is read from Table 7 by conduit trade size, not the conductor.", "Underground cover (Table 53): ≤750 V unprotected = 600 mm non-vehicular / 900 mm vehicular; mechanical protection (plank/concrete) reduces cover by 150 mm.", "Cable through studs: keep 32 mm from the outer edge (12-516) or fit a steel protector plate; min 150 mm free conductor at each box (12-3014).", "Voltage ratings: NMD90 = 300 V, AC90 ≤ 2000 V, TECK90 ≤ 5000 V. Parallel only #1/0 and larger (12-108).", "Support: secure within 300 mm of a box, then ≤1.5 m for cable/armoured (12-510/12-618). NMSC clearances 25 mm heat pipe / 50 mm chimney.", "No splices inside conduit (12-912); PV conductors not in same raceway as other systems (12-904). Box set-back ≤6 mm in non-combustible surfaces, flush in combustible."], "mustKnow_fa": ["fill percentage را مثلِ اسمِ خودت حفظ کن: one conductor 53%، two 31%، three+ 40% (Table 8). زنجیرهٔ محاسبه هم همیشه همین است: Table 10 (areaها) + Table 8 (درصد) + Table 6/9 (conduit size). یک نکته که خیلی‌ها فراموش می‌کنند: bonding conductor در conduit fill شمرده می‌شود.", "Box fill در CEC با NEC فرق دارد، حواست باشد: هر device (receptacle/switch) را یک conductor هم‌اندازهٔ بزرگ‌ترین حساب کن؛ bonding/ground conductor مقدارِ volume جداگانه نمی‌گیرد؛ و wire connectorها هم برخلافِ NEC جداگانه شمرده نمی‌شوند.", "Pull box (12-3036): straight pull = 8 برابرِ trade size بزرگ‌ترین raceway؛ angle یا U pull = 6 برابرِ بزرگ‌ترین + مجموعِ بقیهٔ racewayهایی که از همان wall وارد شده‌اند. دو حالت را قاطی نکن.", "بیشترین number of bends بینِ دو pull point = four 90° bends یعنی 360° (12-940). و یادت باشد bend radius را از Table 7 بر اساسِ trade size لوله می‌خوانی، نه از روی conductor.", "cover (Table 53): تا 750 V و بدونِ protection = 600 mm جایی که non-vehicular است / 900 mm جایی که vehicular است؛ و mechanical protection (plank یا concrete) مقدارِ cover را 150 mm کم می‌کند.", "عبورِ cable از studs: یا 32 mm از outer edge فاصله بده (12-516) یا steel protector plate بگذار؛ و در هر box حداقل 150 mm free conductor بگذار تا بشود کار کرد (12-3014).", "voltage rating ها را بسپار به ذهنت: NMD90 = 300 V، AC90 ≤ 2000 V، TECK90 ≤ 5000 V. و parallel بستن فقط از #1/0 به بالا (12-108).", "Support: اولین support را تا 300 mm از box بزن، بعدش هر ≤1.5 m یکی برای cable/armoured (12-510/12-618). clearanceهای NMSC هم: 25 mm از heat pipe / 50 mm از chimney.", "هیچ splice داخلِ conduit مجاز نیست (12-912)؛ PV conductorها نباید با سیستم‌های دیگر در یک raceway باشند (12-904). box set-back در سطحِ non-combustible مقدارِ ≤6 mm، و در سطحِ combustible باید flush باشد."], "traps": ["Box fill: counting the bonding conductor as a separate volume (it is NOT in the CEC) or counting each wire connector as a conductor like the NEC — both inflate the answer.", "Wrong fill %: using 53% or 31% when there are 3+ conductors — almost always 40% on real exam questions.", "Pull box: applying 8× (straight) when the entries are at an angle/U (should be 6× + sum of others) or vice-versa — read the diagram carefully.", "Bend radius from Table 7 is keyed to the CONDUIT trade size, not the conductor being pulled in.", "Cover depth: forgetting the 150 mm reduction with mechanical protection, or confusing it with the 38 mm plank / 50 mm concrete thickness values.", "Voltage: picking 600 V for NMD90 — it is 300 V. 'EMT is NOT a conduit' wording can flip a fill/bend answer.", "Counting a balanced neutral or bonding conductor when sizing for fill — bond IS counted in conduit fill but NOT in box fill (opposite rules).", "Conduit expansion: forgetting ΔT spans below zero (e.g. -50 to +25 = 75°C, not 25)."], "traps_fa": ["Box fill: اینکه bonding conductor را volume جداگانه بشماری (در CEC این‌طور نیست) یا هر wire connector را مثلِ NEC جدا بشماری — هر دو جوابت را بی‌خود بزرگ می‌کنند و می‌اندازندت.", "fill percentage غلط: وقتی three+ conductor داری ولی باز 53% یا 31% می‌زنی — در سوال‌های واقعی تقریباً همیشه جواب 40% است، حواست باشد.", "Pull box: وقتی entryها angle/U هستند ولی تو 8× (straight) می‌زنی، یا برعکس — باید 6× + مجموعِ بقیه باشد. diagram را با دقت نگاه کن.", "bend radius در Table 7 به trade size لوله بسته است، نه به conductor ای که داخلش کشیده می‌شود — این را زیاد اشتباه می‌گیرند.", "cover: یا کاهشِ 150 mm با mechanical protection را یادت می‌رود، یا آن را با ضخامتِ 38 mm plank / 50 mm concrete قاطی می‌کنی. این دوتا را از هم جدا کن.", "voltage: زدنِ 600 V برای NMD90 در حالی که درستش 300 V است. و این جمله که «EMT یک conduit نیست» می‌تواند کلِ پاسخِ fill یا bend را برگرداند.", "اینجا تله است: bonding conductor در conduit fill شمرده می‌شود اما در box fill نه — قانون این دو دقیقاً برعکسِ هم است؛ balanced neutral را هم درست بشمار.", "conduit expansion: فراموش‌نکن ΔT می‌تواند از زیرِ صفر شروع شود (مثلاً -50 تا +25 می‌شود 75°C، نه 25)."], "mnemonic": "Fill counts down the road: 1-lane 53, 2-lane 31, 3+-lane 40. Pull boxes: STraight = 8 (eight letters in 'straight-ish'), angle/U = 6.", "mnemonic_fa": "fill percentage را مثلِ باریک‌شدنِ خطوطِ جاده تصور کن، رو به پایین می‌رود: one-lane 53، two-lane 31، three+-lane 40. و برای pull box: straight = 8، angle/U = 6.", "method": ["Conduit fill: (1) Table 10 → area of each conductor, sum all; (2) Table 8 → fill % by count (3+ = 40%); (3) Table 6/9 → smallest conduit whose allowable area ≥ total. Reverse for 'how many fit.'", "Box fill: count conductors entering + 1 per device (largest size) — ignore bond volume and connectors; multiply Table 22 mL × equivalents, or read Table 23 directly.", "Pull box: identify straight vs angle/U pulls per the diagram; straight wall = 8× largest, angle/U wall = 6× largest + sum of other entries on that wall.", "Cover/bend/voltage/clearance: pure lookup — go straight to Table 53 / Table 7 / Table D1 / Rule 12-510 and read the matching row.", "Expansion: ΔT = max − min temp; expansion = Table 38 coeff × length (m) × ΔT."], "method_fa": ["conduit fill را سه‌قدمی برو: (1) از Table 10 area هر conductor را بردار و همه را جمع کن؛ (2) از Table 8 درصد را بر اساسِ count بگیر (three+ = 40%)؛ (3) از Table 6/9 کوچک‌ترین conduit ای که allowable area اش ≥ مجموعِ توست را بردار. اگر سوال «چندتا جا می‌شود» بود، همین مسیر را برعکس برو.", "Box fill: conductorهای ورودی را بشمار، به‌ازای هر device هم یکی (به اندازهٔ بزرگ‌ترین) اضافه کن — volume مربوط به bond و connectorها را اصلاً به حساب نیاور؛ بعد mL از Table 22 را در تعدادِ equivalent ضرب کن، یا کلاً مستقیم از Table 23 بخوان.", "Pull box: اول از روی diagram تشخیص بده straight pull است یا angle/U؛ straight wall = 8× بزرگ‌ترین، angle/U wall = 6× بزرگ‌ترین + مجموعِ بقیهٔ entryهای همان wall.", "cover/bend/voltage/clearance: اینها صرفاً lookup است — یک‌راست برو سراغِ Table 53 / Table 7 / Table D1 / Rule 12-510 و ردیفِ منطبق را بخوان، معطل نکن.", "Expansion: اول ΔT = دمای max منهای min؛ بعد expansion = coeff از Table 38 × length (m) × ΔT."], "examples": ["S12-002", "S12-004", "S12-005", "S12-009", "S12-019", "S12-021"], "keywords": [{"kw": "\"conduit fill / minimum conduit size / how many conductors fit\"", "jump": "Rule 12-910 + Tables 6/8/9/10", "why": "1→53%, 2→31%, 3+→40%; sum Table 10 areas, pick smallest conduit", "why_fa": "درصدها را بسپار: 53% / 31% / 40%؛ areaهای Table 10 را جمع کن و کوچک‌ترین conduit را بردار.", "stars": 5}, {"kw": "\"conductor cross-sectional area / area of conductor\"", "jump": "Table 10", "why": "Insulated area feeding every fill calc", "why_fa": "همان insulated area که پایهٔ هر محاسبهٔ fill است.", "stars": 5}, {"kw": "\"box fill / box volume / minimum size of box / how many in a box\"", "jump": "Rule 12-3034/12-3036 + Tables 22/23", "why": "Device = 1 largest conductor; bond adds NO volume", "why_fa": "هر device = یک conductor هم‌اندازهٔ بزرگ‌ترین؛ و bond اینجا volume اضافه نمی‌کند.", "stars": 5}, {"kw": "\"pull box / junction box dimensions / straight vs angle pull\"", "jump": "Rule 12-3036", "why": "Straight = 8× largest raceway; angle/U = 6× + sum of others", "why_fa": "straight = 8× بزرگ‌ترین raceway؛ angle/U = 6× + مجموعِ بقیه.", "stars": 5}, {"kw": "\"minimum cover / buried depth / direct burial\"", "jump": "Rule 12-012 + Table 53", "why": "≤750 V: 600 mm non-veh / 900 mm veh; -150 mm with mech. protection", "why_fa": "تا 750 V: 600 mm non-vehicular / 900 mm vehicular؛ با mechanical protection مقدارِ 150 mm کمتر.", "stars": 5}, {"kw": "\"number of bends / 360 degrees / quarter bends between pulls\"", "jump": "Rule 12-940", "why": "Max equivalent of four 90° bends = 360°", "why_fa": "سقفت equivalent of four 90° bends است، یعنی 360°.", "stars": 4}, {"kw": "\"bend radius / minimum radius of bend\"", "jump": "Table 7", "why": "Radius keyed to conduit trade size, NOT the conductor", "why_fa": "bend radius را trade size لوله تعیین می‌کند، نه conductor.", "stars": 4}, {"kw": "\"NMSC / NMD90 maximum voltage\"", "jump": "Rule 12-552 + Table D1", "why": "NMD90 = 300 V (not 600 V)", "why_fa": "NMD90 سقفش 300 V است، نه 600 V — اینجا گول نخور.", "stars": 4}, {"kw": "\"cable distance from stud / through joists / 32 mm\"", "jump": "Rule 12-516", "why": "32 mm from outer edge or steel protector plate", "why_fa": "یا 32 mm از outer edge، یا steel protector plate.", "stars": 4}, {"kw": "\"free conductor length at outlet / box\"", "jump": "Rule 12-3014", "why": "Minimum 150 mm of free conductor at each box", "why_fa": "در هر box حداقل 150 mm free conductor بگذار تا بشود کار کرد.", "stars": 3}, {"kw": "\"cable type selection / dry-damp-wet / voltage rating of cable\"", "jump": "Table 19 + Table D1", "why": "NMD90=300V, AC90≤2000V, TECK90≤5000V", "why_fa": "NMD90=300V، AC90≤2000V، TECK90≤5000V.", "stars": 3}, {"kw": "\"parallel conductors\"", "jump": "Rule 12-108", "why": "Permitted only #1/0 AWG and larger", "why_fa": "parallel فقط از #1/0 AWG به بالا مجاز است.", "stars": 3}, {"kw": "\"general wiring method / installation requirements\"", "jump": "Rule 12-012 + Section 12 general", "why": "Catch-all for underground/general method rules", "why_fa": "سراغِ این برو وقتی سوال کلیِ wiring method یا underground است.", "stars": 3}, {"kw": "\"support spacing / secured / fastening interval\"", "jump": "Rule 12-510/12-520/12-618 + Table 21", "why": "Within 300 mm of box then ≤1.5 m; Table 21 vertical raceways", "why_fa": "تا 300 mm از box را support بزن، بعد هر ≤1.5 m؛ برای vertical raceway سراغِ Table 21.", "stars": 4}, {"kw": "\"NMSC clearance / heat pipe / chimney\"", "jump": "Rule 12-510", "why": "25 mm from heating pipe, 50 mm from masonry chimney", "why_fa": "25 mm از heating pipe، 50 mm از masonry chimney.", "stars": 3}, {"kw": "\"termination / lug / binding screw / largest conductor without lug\"", "jump": "Rule 12-118", "why": ">#10 needs a lug; #10 solid max under a screw; Belleville washer for Al", "why_fa": "بزرگ‌تر از #10 lug می‌خواهد؛ #10 solid نهایتِ زیرِ binding screw؛ aluminum واشرِ Belleville.", "stars": 3}, {"kw": "\"splices / joints in conduit\"", "jump": "Rule 12-912", "why": "No splices inside conduit — only in accessible boxes/fittings", "why_fa": "داخلِ conduit مجاز نیست splice — فقط در box/fitting قابل‌دسترس.", "stars": 3}, {"kw": "\"wireway / auxiliary gutter fill\"", "jump": "Rule 12-2100 + Table 10", "why": "Max 20% area, max 30 current-carrying conductors", "why_fa": "حداکثر 20% از area و حداکثر 30 current-carrying conductor.", "stars": 2}, {"kw": "\"cable tray clearance\"", "jump": "Rule 12-2202", "why": "300 mm above to ceiling/ducts; 150 mm at short obstructions", "why_fa": "300 mm فاصله از بالا تا ceiling/duct؛ 150 mm کنارِ obstructionهای کوتاه.", "stars": 2}, {"kw": "\"conduit expansion / thermal movement\"", "jump": "Rule 12-1102 + Table 38", "why": "Expansion = coeff × length(m) × ΔT (ΔT spans below zero)", "why_fa": "expansion = coeff × length (m) × ΔT (ΔT می‌تواند از زیرِ صفر شروع شود).", "stars": 2}, {"kw": "\"box set-back / front edge of box / concrete wall\"", "jump": "Rule 12-3018", "why": "≤6 mm set-back in non-combustible; flush in combustible", "why_fa": "box set-back مقدارِ ≤6 mm در non-combustible؛ flush در combustible.", "stars": 2}, {"kw": "\"FCC / flat conductor cable / under-carpet\"", "jump": "Rule 12-806", "why": "Not in dwellings; 30 A max branch; carpet squares ≤750 mm", "why_fa": "در dwelling مجاز نیست؛ branch حداکثر 30 A؛ carpet square مقدارِ ≤750 mm.", "stars": 2}, {"kw": "\"PV conductors in same raceway\"", "jump": "Rule 12-904", "why": "PV conductors must not share raceway with other systems", "why_fa": "PV conductorها نباید با سیستم‌های دیگر در یک raceway باشند.", "stars": 2}, {"kw": "\"EMT in wet location\"", "jump": "Rule 12-1402", "why": "Permitted with wet-rated fittings; EMT is NOT a conduit", "why_fa": "با wet-rated fitting مجاز است؛ یادت باشد EMT یک conduit نیست.", "stars": 2}, {"kw": "\"neutral-supported cable span\"", "jump": "Rule 12-310", "why": "Max span between supports (verify 38 vs 40 m in 2024)", "why_fa": "بیشترین span بینِ supportها (مقدارِ 38 یا 40 m را در نسخهٔ 2024 چک کن).", "stars": 1}]}, {"section": 14, "name": "Overcurrent Protection", "block": "B", "qcount": 11, "importance": 3, "summary": "Fewer questions but high-value and predictable — the ground-fault-protection 'both conditions' rule and basic overcurrent sizing recur almost every exam. Most are one-step rule lookups, so these are easy marks if you know the two thresholds cold.", "summary_fa": "اینجا سوال کمتر است اما هرکدام پرارزش و قابل‌پیش‌بینی‌اند — قانونِ «both conditions» برای ground-fault protection (GFP) و سایزبندیِ پایهٔ overcurrent تقریباً در هر آزمون می‌آیند. بیشترشان یک‌مرحله‌ای و فقط rule lookup اند؛ یعنی اگر آن دو threshold را مثلِ کفِ دستت بلد باشی، اینها نمره‌های مفتیِ تو هستند.", "keyTables": [{"ref": "Table 13", "stars": 4, "what": "Standard overcurrent device ratings", "what_fa": "rating استانداردِ overcurrent device ها، یعنی همان standard sizeهای رسمیِ breaker/fuse (Table 13)", "use": "Pick the standard breaker/fuse size at or below conductor ampacity", "use_fa": "از این table، standard size مربوط به breaker/fuse ای را بردار که برابر یا کمتر از conductor ampacity باشد."}, {"ref": "Table 2", "stars": 3, "what": "Conductor ampacity (Cu in raceway)", "what_fa": "conductor ampacity (copper داخلِ raceway) (Table 2)", "use": "Get ampacity first, then size the OCPD to it (14-104)", "use_fa": "اول ampacity را از اینجا دربیاور، بعد OCPD را بر اساسِ همان سایز کن (14-104) — ترتیبش مهم است."}], "keyRules": [{"ref": "Rule 14-102", "stars": 5, "what": "Ground-fault protection of equipment", "what_fa": "ground-fault protection of equipment (حفاظتِ اتصال‌زمینِ خطا برای تجهیزات) (Rule 14-102)", "note": "Required ONLY if BOTH ≥1000 A AND >150 V to ground; must clear ≥3000 A within 1 s", "note_fa": "فقط وقتی الزامی است که both conditions با هم باشند: ≥1000 A و >150 V to ground؛ و باید جریانِ ≥3000 A را ظرفِ 1 s قطع کند."}, {"ref": "Rule 14-104", "stars": 5, "what": "Overcurrent device rating for conductors", "what_fa": "overcurrent device rating برای conductorها (Rule 14-104)", "note": "≤ conductor ampacity; if no standard size matches, next LOWER standard (with permitted exception to next higher)", "note_fa": "باید ≤ conductor ampacity باشد؛ اگر standard size دقیقاً جور نشد، برو next lower standard size (و در حالتِ permitted exception، next higher)."}, {"ref": "Rule 14-100", "stars": 3, "what": "Overcurrent protection required for each conductor", "what_fa": "الزامِ overcurrent protection برای هر conductor (Rule 14-100)", "note": "Foundation rule — every ungrounded conductor protected", "note_fa": "foundation rule است — هر ungrounded conductor باید protected شود، استثنا ندارد."}, {"ref": "Rule 14-012", "stars": 3, "what": "Interrupting / withstand rating", "what_fa": "interrupting / withstand rating (Rule 14-012)", "note": "Device must safely interrupt available fault current", "note_fa": "device باید بتواند available fault current آن نقطه را سالم و بی‌خطر interrupt کند."}, {"ref": "Rule 14-606", "stars": 3, "what": "Breaker interrupting rating", "what_fa": "breaker interrupting rating (Rule 14-606)", "note": "Default 10 000 A symmetrical unless marked higher", "note_fa": "پیش‌فرضش 10 000 A symmetrical است، مگر روی خودش عددِ بالاتری زده باشند."}, {"ref": "Rule 14-200", "stars": 2, "what": "Plug fuses", "what_fa": "plug fuse ها (Rule 14-200)", "note": "Max 30 A (Type T / Type S)", "note_fa": "سقفش 30 A است (Type T / Type S)."}, {"ref": "Rule 14-212", "stars": 2, "what": "Fuse type for cyclic loads (heating)", "what_fa": "fuse type برای cyclic load ها مثلِ heating (Rule 14-212)", "note": "Time-delay / HRC type", "note_fa": "از نوعِ time-delay یا HRC، تا با جریانِ رفت‌وبرگشتیِ بار نسوزد."}, {"ref": "Rule 14-500/14-510", "stars": 2, "what": "Switch ratings", "what_fa": "switch ratings (Rule 14-500/14-510)", "note": "Tungsten ('T') rated for incandescent; knife switch limits", "note_fa": "switch ردهٔ Tungsten («T») برای incandescent؛ و محدودیت‌های knife switch را هم همین‌جا ببین."}], "mustKnow": ["GFP rule (14-102): equipment ground-fault protection required ONLY when BOTH conditions are true — service rated 1000 A or more AND more than 150 V to ground. 208Y/120 V (120 V to ground) never qualifies; 600/347 V qualifies only at ≥1000 A.", "GFP clearing time: a ground-fault current of 3000 A or more must be cleared within a maximum of 1 second (14-102).", "Overcurrent vs overload: overcurrent (fuse/breaker, Section 14) protects the CONDUCTORS; overload (thermal, Section 28) protects the MOTOR — the single most-confused exam pair.", "OCPD sizing (14-104): device rating ≤ conductor ampacity; where ampacity doesn't equal a standard size, use the next LOWER standard size from Table 13 (a permitted exception allows next higher for non-continuous loads ≤ certain ratings).", "Breaker default interrupting rating = 10 000 A symmetrical unless specifically marked otherwise (14-606); plug fuse max = 30 A (14-200)."], "mustKnow_fa": ["قانونِ GFP (14-102) را این‌طور قفل کن: ground-fault protection فقط وقتی الزامی است که both conditions با هم برقرار باشند — service رتبهٔ 1000 A یا بیشتر، و more than 150 V to ground. سیستمِ 208Y/120 V (که 120 V to ground است) هیچ‌وقت مشمول نمی‌شود؛ 600/347 V هم فقط وقتی به ≥1000 A برسد مشمول می‌شود.", "clearing time مربوط به GFP: هر ground-fault current رتبهٔ 3000 A یا بیشتر باید ظرفِ حداکثر 1 second قطع شود (14-102) — این عدد را همان‌طور حفظ کن.", "overcurrent در برابر overload را با هم اشتباه نگیر: overcurrent (fuse/breaker، Section 14) از conductor محافظت می‌کند؛ overload (thermal، Section 28) از motor. این پرتکرارترین جفتِ اشتباهیِ کلِ آزمون است.", "سایزبندیِ OCPD (14-104): rating دستگاه ≤ conductor ampacity؛ هر جا ampacity دقیقاً به standard size نخورد، next lower standard size از Table 13 را بردار (یک permitted exception برای non-continuous loadهای زیرِ ردهٔ مشخص، اجازهٔ رفتن به next higher را می‌دهد).", "breaker interrupting rating پیش‌فرض = 10 000 A symmetrical، مگر روی خودش صراحتاً عددِ دیگری زده باشند (14-606)؛ و سقفِ plug fuse هم 30 A است (14-200)."], "traps": ["GFP: answering 'Yes' when only ONE of the two conditions is met — high current at low voltage (2000 A, 208 V) or high voltage at low current (800 A, 347 V) both = NO.", "Confusing overcurrent (protects wire) with overload (protects motor) — they are different sections and different sizing bases.", "Sizing the breaker to the LOAD instead of the CONDUCTOR ampacity, or rounding UP to next standard size when 14-104 calls for next lower.", "Assuming a higher interrupting rating than the 10 000 A default just because voltage/frame size is large.", "Treating 150 V to ground as exclusive — '>150 V' means 347 V qualifies but 150 V itself does not."], "traps_fa": ["GFP: «بله» گفتن وقتی فقط یکی از دو condition برقرار است — current بالا با voltage پایین (2000 A، 208 V) یا voltage بالا با current پایین (800 A، 347 V) هر دو جوابشان «خیر» است.", "overcurrent (محافظِ conductor) را با overload (محافظِ motor) قاطی کردن — اینها در دو Section جدا و با دو مبنای سایزبندیِ متفاوت‌اند.", "breaker را روی load سایز کردن به جای conductor ampacity، یا rounding up (next standard size) در حالی که 14-104 سایزِ next lower را می‌خواهد.", "فرضِ interrupting rating بالاتر از پیش‌فرضِ 10 000 A، فقط چون voltage یا frame size بزرگ به نظر می‌رسد.", "150 V to ground را شامل دانستن — «>150 V» یعنی 347 V مشمول است، ولی خودِ 150 V مشمول نیست؛ علامتِ «بزرگ‌تر از» را دست‌کم نگیر."], "mnemonic": "GFP needs the GRAND SLAM: 1000 A AND 150 V — BOTH bases or you're OUT (no GFP).", "mnemonic_fa": "GFP مثلِ GRAND SLAM است: هم 1000 A، هم 150 V — باید both base را با هم بزنی، وگرنه بازی تمام است (GFP لازم نیست).", "method": ["Ground-fault protection: check BOTH gates — is it ≥1000 A? AND is it >150 V to ground? Only 'yes' to both → GFP required. Either 'no' → not required.", "Conductor overcurrent: (1) Table 2/4 → conductor ampacity; (2) Rule 14-104 → set OCPD ≤ that ampacity; (3) Table 13 → nearest standard size (next lower unless exception applies).", "Device rating questions (plug fuse, knife switch, interrupting rating): straight rule lookup — go to 14-200 / 14-510 / 14-606 and read the limit."], "method_fa": ["ground-fault protection: دو gate را پشتِ‌سرِ هم چک کن — اول آیا ≥1000 A است؟ بعد آیا >150 V to ground است؟ فقط اگر به both «بله» گفتی ← GFP الزامی. کافی است یکی «خیر» شود ← لازم نیست.", "conductor overcurrent را سه‌قدمی برو: (1) از Table 2/4 conductor ampacity را بگیر؛ (2) با Rule 14-104 رتبهٔ OCPD را ≤ همان ampacity بگذار؛ (3) از Table 13 نزدیک‌ترین standard size را بردار (next lower، مگر exception اعمال شود).", "سوال‌های device rating (plug fuse، knife switch، interrupting rating): اینها فقط rule lookup مستقیم‌اند — برو 14-200 / 14-510 / 14-606 و عددِ حد را بخوان، تمام."], "examples": ["S14-001", "S14-005", "S14-007", "S14-009", "S14-011"], "keywords": [{"kw": "\"is ground-fault protection required / GFP service\"", "jump": "Rule 14-102", "why": "ONLY if BOTH ≥1000 A AND >150 V to ground", "why_fa": "فقط اگر both با هم: ≥1000 A و >150 V to ground.", "stars": 5}, {"kw": "\"overcurrent / breaker or fuse size for a conductor\"", "jump": "Rule 14-104 + Table 13", "why": "≤ conductor ampacity; next LOWER standard size", "why_fa": "≤ conductor ampacity؛ بعد next lower standard size.", "stars": 5}, {"kw": "\"ground-fault clearing time / 3000 A\"", "jump": "Rule 14-102", "why": "≥3000 A fault cleared within max 1 second", "why_fa": "ground-fault رتبهٔ ≥3000 A باید ظرفِ حداکثر 1 second قطع شود.", "stars": 4}, {"kw": "\"overcurrent vs overload / what protects the wire\"", "jump": "Rule 14-100 (vs Section 28)", "why": "Overcurrent protects conductors; overload protects the motor", "why_fa": "overcurrent از conductor محافظت می‌کند، overload از motor — قاطی نکن.", "stars": 4}, {"kw": "\"overcurrent protection required per conductor\"", "jump": "Rule 14-100", "why": "Every ungrounded conductor must be protected", "why_fa": "هر ungrounded conductor باید protected شود.", "stars": 3}, {"kw": "\"interrupting rating / available fault current / withstand\"", "jump": "Rule 14-012 + 14-606", "why": "Default 10 000 A symmetrical unless marked higher", "why_fa": "interrupting rating پیش‌فرض 10 000 A symmetrical، مگر عددِ بالاتری رویش زده باشند.", "stars": 3}, {"kw": "\"maximum breaker for a load / non-continuous\"", "jump": "Rule 14-104 + Table 2 + Table 13", "why": "Size to conductor ampacity, then standard size", "why_fa": "اول روی conductor ampacity سایز کن، بعد standard size.", "stars": 3}, {"kw": "\"plug fuse maximum rating\"", "jump": "Rule 14-200", "why": "Plug fuse max = 30 A (Type T / Type S)", "why_fa": "سقفِ plug fuse = 30 A (Type T / Type S).", "stars": 2}, {"kw": "\"fuse type for heating / cyclic load\"", "jump": "Rule 14-212", "why": "Time-delay / HRC-type fuse (Type D or P)", "why_fa": "fuse از نوعِ time-delay یا HRC (Type D یا P).", "stars": 2}, {"kw": "\"knife switch rating / general-use switch\"", "jump": "Rule 14-510", "why": "Knife switch max ~750 V / 600 A (verify)", "why_fa": "سقفِ knife switch حدودِ 750 V / 600 A (چک کن).", "stars": 2}, {"kw": "\"switch rating for incandescent / tungsten / T-rated\"", "jump": "Rule 14-500", "why": "Tungsten ('T') rated for high lamp inrush", "why_fa": "switch ردهٔ Tungsten («T») برای lamp inrush بالای incandescent.", "stars": 2}, {"kw": "\"overcurrent for equipment wire / small conductor\"", "jump": "Rule 14-104 + Table 13", "why": "#16 equipment wire OCP per Table 13 limits", "why_fa": "overcurrent protection برای equipment wire رتبهٔ #16 طبقِ حدودِ Table 13.", "stars": 2}]}, {"section": 16, "name": "Class 1 & 2 Circuits", "block": "E", "qcount": 15, "importance": 3, "summary": "Low-question-count but easy marks: it all turns on Class 1 vs Class 2 (power-limited) and the extra-low-voltage 30 V boundary. Most questions are straight rule lookups in 16-200/16-210/16-212 plus the ELC/LVT ampacity table.", "keyTables": [{"ref": "Table 11", "stars": 3, "what": "ELC / LVT cable ampacity, derated by conductor count", "use": "look up base #16 AWG ampacity then derate for the number of conductors in the cable", "what_fa": "ampacity (جریان‌دهیِ مجاز) کابلِ ELC/LVT که با زیاد شدنِ conductor count (تعدادِ هادی) داخلِ کابل، derate (کاهش) می‌شود", "use_fa": "اول base ampacity برای #16 AWG را از Table 11 بخوان، بعد بر اساسِ conductor count داخلِ کابل آن را derate کن — هر چه conductor بیشتر، heat بیشتر، پس ampacity کمتر"}], "keyRules": [{"ref": "Rule 16-200", "stars": 5, "what": "Class 1 / Class 2 power-source limits", "note": "ELV = max 30 V; Class 1 ELV power = 30 V / 1000 VA; Class 2 above 30 V limited to 100 VA (so fuse = 100 VA ÷ V)", "what_fa": "power-source limit (سقفِ توانِ منبع) برای مدارهای Class 1 و Class 2", "note_fa": "ELV (extra-low-voltage / ولتاژِ فوق‌کم) یعنی max 30 V؛ Class 1 ELV power circuit تا 30 V و 1000 VA مجاز است؛ اما Class 2 بالای 30 V را خودِ code به 100 VA قفل می‌کند — پس max fuse را از روی همین limit بگیر: fuse = 100 VA ÷ V"}, {"ref": "Rule 16-210", "stars": 5, "what": "Class 2 conductor sizing, ELC use, small Class 1 conductor overcurrent", "note": "smallest Class 2 conductor = #30 AWG; #18 Class 1 conductor max 5 A, #16 max 7 A", "what_fa": "Class 2 conductor sizing، کاربردِ ELC conductor، و overcurrent protection برای conductorهای نازکِ Class 1", "note_fa": "چون Class 2 power-limited است، تا نازکیِ #30 AWG هم مجاز است؛ ولی برای Class 1 control conductor یک overcurrent limit داریم: #18 max 5 A و #16 max 7 A"}, {"ref": "Rule 16-212", "stars": 5, "what": "Separation of Class 2 from light/power/Class 1 conductors", "note": "where neither in raceway: 50 mm at ≤300 V, 600 mm at higher voltage (480 V)", "what_fa": "separation (فاصله‌گذاری) مدارهای Class 2 از light/power conductor و از Class 1 conductor", "note_fa": "وقتی هیچ‌کدام داخلِ raceway (لوله) نیستند: در ≤300 V فاصلهٔ 50 mm و در ولتاژِ بالاتر (مثلِ 480 V) فاصلهٔ 600 mm کافی است — منطقش هم همین است: voltage بالاتر، spacing بیشتر"}, {"ref": "Rule 16-100", "stars": 3, "what": "Class 1 vs Class 2 classification", "note": "fire alarm = Class 1 life-safety even at 24 V", "what_fa": "classification (تفکیک) Class 1 از Class 2", "note_fa": "حواست باشد: fire alarm circuit یک life-safety (ایمنیِ‌جانی) است و Class 1 حساب می‌شود، حتی اگر فقط 24 V باشد — پایین بودنِ voltage گول‌زننده است"}, {"ref": "Rule 32-100", "stars": 3, "what": "Fire alarm conductor wiring (cross-ref from Sec 16)", "note": "#18 single / #19 minimum in an integral assembly of 4+ conductors", "what_fa": "fire alarm conductor wiring (ارجاعِ متقابل از Section 16)", "note_fa": "min size: اگر single conductor باشد #18، و اگر داخلِ یک integral assembly از 4+ conductor باشد، #19 هم پذیرفته می‌شود"}], "mustKnow": ["Extra-low-voltage = not exceeding 30 V (boundary inclusive: 30 V is ELV)", "Class 2 = power-limited; smallest permitted conductor = #30 AWG", "Class 1 ELV power circuit max = 30 V and 1000 VA (16-200)", "Class 2 above 30 V limited to 100 VA → max fuse = 100 VA ÷ operating voltage", "Separation (neither in raceway): 50 mm at ≤300 V, 600 mm above (≈480 V)", "Fire alarm circuits are Class 1, not Class 2 — ELC wire is NOT permitted for fire alarm", "Small Class 1 control conductor overcurrent: #18 = 5 A, #16 = 7 A"], "traps": ["Calling a 24 V fire alarm circuit 'Class 2' because the voltage is low — it is Class 1 (life-safety)", "Using TEW/equipment wire for open Class 2 field wiring — only conductors approved for Class 2 (e.g. ELC) are allowed when not in a raceway", "Confusing the 50 mm (≤300 V) and 600 mm (higher voltage) separations in 16-212", "Forgetting the 100 VA limit on Class 2 above 30 V — that VA cap sets the max fuse, not a fixed amp value"], "mnemonic": "Class 2 = power-limited (100 VA above 30 V); Fire Alarm = Class 1 (Life = Class 1).", "method": ["Classification question → 16-100: is it life-safety (fire alarm)? → Class 1. Otherwise check if power-limited → Class 2.", "Class 2 max fuse above 30 V → 100 VA ÷ operating voltage.", "Separation question → 16-212: ≤300 V = 50 mm, higher = 600 mm (when neither is in a raceway).", "Conductor/cable ampacity → Table 11, base AWG ampacity then derate for conductor count."], "examples": ["S16-002", "S16-005", "S16-007", "S16-010", "S16-013"], "keywords": [{"kw": "\"Class 2 / power-limited circuit\"", "jump": "Rule 16-200 / 16-210", "why": "power-limited; smallest conductor #30 AWG", "stars": 5, "why_fa": "power-limited است؛ چون power کم است smallest conductor تا #30 AWG مجاز است"}, {"kw": "\"smallest conductor size, Class 2\"", "jump": "Rule 16-210", "why": "#30 AWG permitted (power-limited)", "stars": 5, "why_fa": "چون power-limited است، smallest conductor تا #30 AWG مجاز است"}, {"kw": "\"max fuse / overcurrent, Class 2 above 30 V\"", "jump": "Rule 16-200", "why": "100 VA cap → 100 ÷ V (e.g. 100/150 = 0.67 A)", "stars": 5, "why_fa": "100 VA cap ← fuse = 100 ÷ V (مثلاً در 150 V می‌شود 100/150 = 0.67 A)"}, {"kw": "\"Class 1 ELV power circuit max V and VA\"", "jump": "Rule 16-200", "why": "30 V and 1000 VA", "stars": 5, "why_fa": "max یعنی 30 V و 1000 VA"}, {"kw": "\"extra-low-voltage limit / max ELV voltage\"", "jump": "Rule 16-200 (Sec 0 definition)", "why": "30 V — boundary is inclusive", "stars": 5, "why_fa": "30 V — و خودِ این boundary هم inclusive و داخلِ ELV حساب می‌شود"}, {"kw": "\"separation Class 2 from power / Class 1\"", "jump": "Rule 16-212", "why": "50 mm at ≤300 V, 600 mm higher (neither in raceway)", "stars": 5, "why_fa": "50 mm در ≤300 V و 600 mm در higher voltage (وقتی هیچ‌کدام داخلِ raceway نیست)"}, {"kw": "\"Class 1 vs Class 2 / fire alarm classification\"", "jump": "Rule 16-100 / 32-100", "why": "fire alarm = Class 1 life-safety even at 24 V", "stars": 4, "why_fa": "fire alarm یعنی Class 1 و life-safety، حتی در 24 V"}, {"kw": "\"ELC conductor / extra-low-voltage control wire\"", "jump": "Rule 16-210", "why": "Class 2 only, max 30 V; NOT for fire alarm", "stars": 4, "why_fa": "فقط برای Class 2 و max 30 V؛ برای fire alarm مجاز نیست"}, {"kw": "\"TEW / equipment wire in open Class 2 wiring\"", "jump": "Rule 16-210 / 16-212", "why": "equipment wire NOT approved for open Class 2", "stars": 3, "why_fa": "equipment wire برای open Class 2 wiring approved نیست"}, {"kw": "\"ELC / LVT cable ampacity (multi-conductor)\"", "jump": "Table 11", "why": "base AWG ampacity, derate by conductor count", "stars": 3, "why_fa": "base ampacity بر حسبِ AWG، بعد derate بر اساسِ conductor count"}, {"kw": "\"#18 / #16 Class 1 conductor overcurrent\"", "jump": "Rule 16-210", "why": "#18 = 5 A, #16 = 7 A max", "stars": 3, "why_fa": "overcurrent limit: #18 max 5 A و #16 max 7 A"}, {"kw": "\"fire alarm conductor minimum size\"", "jump": "Rule 32-100", "why": "#18 single, #19 in integral 4+ conductor assembly", "stars": 2, "why_fa": "single conductor یعنی #18، و در integral assembly از 4+ conductor یعنی #19"}], "summary_fa": "تعدادِ سوالش کم است ولی نمره‌اش راحت به جیب می‌رود: همهٔ ماجرا سرِ فرقِ Class 1 با Class 2 (power-limited / توان‌محدود) و مرزِ 30 V برای ELV (extra-low-voltage / ولتاژِ فوق‌کم) می‌چرخد. بیشترِ سوال‌ها یک rule lookup ساده در Rule 16-200/16-210/16-212 و ELC/LVT ampacity table است؛ پس این چند rule را سرِ انگشتت داشته باش.", "mustKnow_fa": ["ELV (extra-low-voltage) یعنی not exceeding 30 V — و دقت کن boundary خودش هم inclusive است؛ یعنی خودِ 30 V هنوز ELV حساب می‌شود", "Class 2 = power-limited؛ به همین خاطر smallest conductor تا #30 AWG مجاز است", "Class 1 ELV power circuit حداکثر 30 V و 1000 VA است (Rule 16-200)", "Class 2 بالای 30 V به 100 VA قفل است ← max fuse = 100 VA ÷ operating voltage", "separation (وقتی هیچ‌کدام داخلِ raceway نیست): 50 mm در ≤300 V و 600 mm در ولتاژِ بالاتر (≈480 V)", "fire alarm circuit یعنی Class 1 نه Class 2 — و ELC wire را اصلاً برای fire alarm به کار نبر", "overcurrent limit برای Class 1 control conductor نازک: #18 max 5 A و #16 max 7 A"], "traps_fa": ["اینکه یک fire alarm circuit با 24 V را فقط به‌خاطرِ voltage پایینش Class 2 بنامی — نه! این circuit یک life-safety و Class 1 است", "به‌کار بردنِ equipment wire (TEW) برای open field wiring از نوعِ Class 2 — وقتی داخلِ raceway نیست فقط conductorِ approved برای Class 2 (مثلِ ELC) مجاز است", "قاطی کردنِ دو separation در Rule 16-212: 50 mm مالِ ≤300 V است و 600 mm مالِ higher voltage؛ جابه‌جا نزن", "از یاد بردنِ 100 VA limit برای Class 2 بالای 30 V — یادت باشد این VA همان max fuse را تعیین می‌کند، نه یک fixed amp value"], "method_fa": ["classification question ← اول برو سراغِ Rule 16-100: life-safety (fire alarm) است؟ پس Class 1. اگر نه، ببین power-limited است یا نه ← Class 2.", "Class 2 max fuse بالای 30 V ← به‌سادگی 100 VA ÷ operating voltage.", "separation question ← Rule 16-212: در ≤300 V بزن 50 mm، در higher voltage بزن 600 mm (به شرطِ اینکه هیچ‌کدام داخلِ raceway نباشد).", "conductor/cable ampacity ← Table 11: اول base ampacity بر حسبِ AWG، بعد بر اساسِ conductor count آن را derate کن."], "mnemonic_fa": "Class 2 = power-limited (بالای 30 V سقفِ 100 VA)؛ fire alarm = Class 1 (Life یعنی Class 1)."}, {"section": 26, "name": "Equipment & Receptacles", "block": "B", "qcount": 53, "importance": 4, "summary": "High question count, mostly fast lookups: receptacle spacing/placement, GFCI/AFCI rules, panelboard handle height, transformer/capacitor protection and clearances. Know the dwelling receptacle rules cold — they are near-guaranteed easy marks.", "keyTables": [{"ref": "Table 50", "stars": 3, "what": "Transformer overcurrent device max % (primary/secondary, ≤750 V vs >750 V)", "use": "for transformer fuse/breaker sizing in 26-250/26-252", "what_fa": "max % برای overcurrent device ترانسفورمر (transformer) — هم primary و هم secondary، و با تفکیکِ ≤750 V از >750 V", "use_fa": "وقتی می‌خواهی fuse/breaker ترانسفورمر را در Rule 26-250/26-252 سایز کنی، % را از همین Table 50 بردار — مراقبِ voltage column درست باش"}, {"ref": "Table 13", "stars": 3, "what": "Standard overcurrent device (fuse/breaker) sizes", "use": "round the calculated transformer/capacitor OCPD to a standard size", "what_fa": "standard size های overcurrent device (fuse/breaker)", "use_fa": "بعد از اینکه OCPD ترانسفورمر/capacitor را حساب کردی، عددش معمولاً سرراست نیست — با Table 13 به standard size مجاز round کن"}], "keyRules": [{"ref": "Rule 26-712", "stars": 5, "what": "Dwelling receptacle spacing & counter/island requirements", "note": "no point on usable wall floor line >1.8 m from a receptacle → max 3.6 m apart", "what_fa": "receptacle spacing (فاصله‌گذاریِ پریز) در dwelling و الزاماتِ counter/island", "note_fa": "منطقش این است: هیچ نقطه‌ای روی wall floor line قابل‌استفاده نباید بیش از 1.8 m تا یک receptacle فاصله داشته باشد — پس وقتی دو طرفِ یک نقطه receptacle باشد، receptacle ها تا 3.6 m از هم فاصله می‌گیرند"}, {"ref": "Rule 26-700", "stars": 5, "what": "Receptacle general rules / faceplate / GFCI near sinks", "note": "face projects ≥0.4 mm past metal plate; GFCI within 1.5 m of a sink", "what_fa": "general rule های receptacle / faceplate / و الزامِ GFCI نزدیکِ sink", "note_fa": "face پریز باید حداقل 0.4 mm از metal faceplate بیرون بزند (تا فلز با live تماس نگیرد)؛ و هر receptacle که در 1.5 m از یک sink باشد باید GFCI شود"}, {"ref": "Rule 26-714", "stars": 5, "what": "Outdoor receptacle GFCI (Class A) within 2.5 m of grade", "note": "residential outdoor ≤2.5 m of finished grade = Class A GFCI", "what_fa": "الزامِ Class A GFCI برای outdoor receptacle در 2.5 m از grade (سطحِ زمین)", "note_fa": "هر outdoor residential receptacle که تا 2.5 m از finished grade دسترس‌پذیر باشد، باید Class A GFCI داشته باشد — چون احتمالِ تماس با moisture و ground بالاست"}, {"ref": "Rule 26-722", "stars": 5, "what": "Dwelling branch-circuit / AFCI / dedicated-circuit requirements", "note": "combination-type AFCI for 125 V receptacles ≤20 A; dedicated circuits (central vac, etc.)", "what_fa": "الزاماتِ branch circuit، AFCI و dedicated circuit در dwelling", "note_fa": "برای 125 V receptacle با جریانِ ≤20 A در dwelling یک combination-type AFCI لازم است؛ ضمناً بعضی load ها (مثلِ central vac) باید dedicated circuit خودشان را داشته باشند"}, {"ref": "Rule 26-724", "stars": 4, "what": "Required dwelling receptacles (outdoor, etc.)", "note": "min 2 outdoor duplex receptacles readily accessible from grade", "what_fa": "required receptacle های dwelling (از جمله outdoor)", "note_fa": "min 2 outdoor duplex receptacle لازم است که از grade به‌راحتی readily accessible باشند"}, {"ref": "Rule 26-210", "stars": 4, "what": "Capacitor conductor & overcurrent sizing", "note": "conductor ampacity ≥135% of capacitor rated current", "what_fa": "conductor و overcurrent sizing برای capacitor (خازن)", "note_fa": "ampacity هادیِ capacitor باید حداقل 135% از capacitor rated current باشد — این 135% را با 125% branch موتور قاطی نکن"}, {"ref": "Rule 26-400", "stars": 4, "what": "Panelboard installation / handle height", "note": "highest operating handle ≤1.7 m above finished floor", "what_fa": "panelboard installation و handle height (ارتفاعِ دسته)", "note_fa": "highest operating handle نباید بیشتر از 1.7 m بالای finished floor باشد — یعنی باید بدونِ نردبان قابلِ دسترس باشد"}, {"ref": "Rule 26-244", "stars": 3, "what": "Dry-type transformer wall/floor clearance", "note": "floor-mounted dry-type ≈150 mm from wall for ventilation", "what_fa": "wall/floor clearance برای dry-type transformer (ترانسفورمرِ خشک)", "note_fa": "یک floor-mounted dry-type transformer باید حدودِ 150 mm از wall فاصله بگیرد تا ventilation داشته باشد و خنک بماند"}, {"ref": "Rule 26-250 / 26-252", "stars": 3, "what": "Transformer overcurrent protection (interrupting rating, primary OCPD)", "note": "OCPD % from Table 50; secondary fault = FLA ÷ per-unit impedance", "what_fa": "transformer overcurrent protection (interrupting rating و primary OCPD)", "note_fa": "OCPD % را از Table 50 بردار؛ و secondary fault current را اینطور حساب کن: FLA ÷ per-unit impedance (امپدانسِ پریونیت)"}], "mustKnow": ["Receptacle spacing (26-712): max 3.6 m apart (no point >1.8 m from a receptacle)", "Panelboard handle height (26-400): max 1.7 m above finished floor", "Receptacle face projects ≥0.4 mm beyond a metal faceplate (26-700)", "Range receptacle centre ≤130 mm above finished floor (26-744)", "Outdoor residential receptacle within 2.5 m of grade = Class A GFCI (26-714)", "GFCI within 1.5 m of a sink (26-700)", "Combination AFCI for dwelling 125 V receptacles ≤20 A (26-722)", "Capacitor conductor ≥135% of rated current (26-210)", "≥2 outdoor duplex receptacles required at a single dwelling (26-724)", "Transformer secondary fault current = secondary FLA ÷ per-unit impedance"], "traps": ["Reading 26-712 as '1.8 m apart' — the 1.8 m is the distance from any point to a receptacle, so receptacles are up to 3.6 m apart", "Applying GFCI to a dedicated stationary-appliance receptacle (washer behind machine, sump pump) — those have exceptions", "Forgetting the 2.5 m-of-grade trigger for outdoor GFCI (26-714)", "Confusing capacitor 135% conductor rule (26-210) with the 125% motor branch rule (28-106)", "Using the ≤750 V transformer OCPD % when the primary is >750 V (different Table 50 column → e.g. 300% permitted)", "Handle height: 1.7 m is the max, not 2.1 m or 1.5 m"], "mnemonic": "Receptacles: 1.8 to a point, 3.6 between; Panel handle 1.7; Range 130; Outdoor GFCI within 2.5 of grade.", "method": ["Dwelling receptacle spacing/placement → 26-712 (1.8 m / 3.6 m, counter & island rules).", "GFCI question → near sink (1.5 m) or outdoor ≤2.5 m grade → Class A GFCI, then check dedicated-appliance exceptions.", "AFCI / dedicated-circuit dwelling question → 26-722.", "Capacitor → 26-210: conductor ≥135% of rated current; rated current = kVA ÷ (V × √3 for 3-φ).", "Transformer OCPD → primary current, then Table 50 % (watch ≤750 V vs >750 V), round with Table 13.", "Transformer fault/interrupting rating → secondary FLA ÷ per-unit impedance."], "examples": ["S26-003", "S26-004", "S26-013", "S26-019", "S26-026", "S26-001"], "keywords": [{"kw": "\"receptacle spacing in a dwelling\"", "jump": "Rule 26-712", "why": "no point >1.8 m from a receptacle → max 3.6 m apart", "stars": 5, "why_fa": "هیچ point بیش از 1.8 m از receptacle نباشد ← پس max 3.6 m بینِ receptacle ها"}, {"kw": "\"kitchen counter / island receptacle required\"", "jump": "Rule 26-712", "why": "counter & island dimension thresholds trigger a receptacle", "stars": 4, "why_fa": "وقتی dimension همان counter یا island از یک threshold بزرگ‌تر شود، یک receptacle اجباری می‌شود"}, {"kw": "\"GFCI required? (sink / kitchen / outdoor)\"", "jump": "Rule 26-700", "why": "within 1.5 m of a sink → Class A GFCI", "stars": 5, "why_fa": "تا 1.5 m از یک sink ← باید Class A GFCI شود"}, {"kw": "\"outdoor receptacle within 2.5 m of grade\"", "jump": "Rule 26-714", "why": "residential ≤2.5 m grade = Class A GFCI", "stars": 5, "why_fa": "outdoor residential تا 2.5 m از grade = Class A GFCI"}, {"kw": "\"AFCI / combination arc-fault, dwelling\"", "jump": "Rule 26-722", "why": "125 V receptacles ≤20 A in dwelling need combo AFCI", "stars": 5, "why_fa": "125 V receptacle با ≤20 A در dwelling یک combination AFCI می‌خواهد"}, {"kw": "\"dedicated branch circuit (central vac, fridge, etc.)\"", "jump": "Rule 26-722", "why": "lists which dwelling loads need their own circuit + exceptions", "stars": 4, "why_fa": "فهرستِ load هایی که باید dedicated circuit خودشان را داشته باشند، به‌علاوهٔ exception ها"}, {"kw": "\"required dwelling receptacles (outdoor count)\"", "jump": "Rule 26-724", "why": "min 2 outdoor duplex readily accessible from grade", "stars": 4, "why_fa": "min 2 outdoor duplex receptacle که از grade readily accessible باشد"}, {"kw": "\"panelboard handle height\"", "jump": "Rule 26-400", "why": "highest handle ≤1.7 m above finished floor", "stars": 5, "why_fa": "highest handle max 1.7 m بالای finished floor"}, {"kw": "\"receptacle face / metal faceplate projection\"", "jump": "Rule 26-700", "why": "face ≥0.4 mm beyond metal plate", "stars": 3, "why_fa": "face پریز حداقل 0.4 mm از metal faceplate بیرون بزند"}, {"kw": "\"range receptacle height\"", "jump": "Rule 26-744", "why": "centre ≤130 mm above finished floor", "stars": 3, "why_fa": "centre پریز max 130 mm بالای finished floor"}, {"kw": "\"capacitor conductor / fuse sizing\"", "jump": "Rule 26-210", "why": "conductor ≥135% of capacitor rated current", "stars": 4, "why_fa": "conductor حداقل 135% از capacitor rated current"}, {"kw": "\"transformer overcurrent / primary fuse or breaker\"", "jump": "Rule 26-250 / 26-252 + Table 50", "why": "OCPD % differs ≤750 V vs >750 V; round with Table 13", "stars": 4, "why_fa": "OCPD % در ≤750 V و >750 V فرق دارد؛ آخرش با Table 13 round کن"}, {"kw": "\"transformer fault current / interrupting rating\"", "jump": "Rule 26-250", "why": "secondary FLA ÷ per-unit impedance", "stars": 3, "why_fa": "secondary FLA ÷ per-unit impedance"}, {"kw": "\"dry-type transformer wall / floor clearance\"", "jump": "Rule 26-244", "why": "floor-mounted ≈150 mm from wall for ventilation", "stars": 3, "why_fa": "floor-mounted حدودِ 150 mm از wall برای ventilation و خنک‌شدن"}, {"kw": "\"liquid-filled transformer / capacitor vault\"", "jump": "Rule 26-350 / 26-012", "why": "vault/containment required above a liquid-quantity threshold", "stars": 2, "why_fa": "بالای یک liquid-quantity threshold، vault/containment (محفظه/مهار) اجباری می‌شود"}, {"kw": "\"fence / enclosure clearance to live parts\"", "jump": "Rule 26-302", "why": "min 1 m to enclosure; larger to unguarded live parts by voltage", "stars": 2, "why_fa": "min 1 m تا enclosure؛ و تا unguarded live parts بسته به voltage بیشتر"}, {"kw": "\"corridor receptacle spacing (apartment)\"", "jump": "Rule 26-710", "why": "max 15 m between duplex receptacles in public corridors", "stars": 2, "why_fa": "در public corridor ها max 15 m بینِ duplex receptacle ها"}, {"kw": "\"rooftop / HVAC maintenance receptacle\"", "jump": "Rule 26-708 / 26-714", "why": "5-20R, GFCI protected", "stars": 2, "why_fa": "از نوعِ 5-20R و با GFCI protection"}], "summary_fa": "این بلوک سوالش زیاد است ولی بیشترش fast lookup است: receptacle spacing و placement، قوانینِ GFCI/AFCI، panelboard handle height، و protection و clearance برای transformer/capacitor. توصیهٔ من: dwelling receptacle rule ها را مثلِ کفِ دست حفظ کن — اینها تقریباً نمرهٔ آسانِ تضمینی‌اند.", "mustKnow_fa": ["receptacle spacing (Rule 26-712): max 3.6 m بین receptacle ها — چون هیچ نقطه‌ای نباید بیش از 1.8 m از یک receptacle فاصله داشته باشد", "panelboard handle height (Rule 26-400): highest handle max 1.7 m بالای finished floor", "face پریز باید حداقل 0.4 mm از metal faceplate بیرون بزند (Rule 26-700)", "centre پریزِ range max 130 mm بالای finished floor (Rule 26-744)", "outdoor residential receptacle تا 2.5 m از grade = Class A GFCI (Rule 26-714)", "هر receptacle تا 1.5 m از یک sink باید GFCI باشد (Rule 26-700)", "combination AFCI برای 125 V receptacle های dwelling با جریانِ ≤20 A (Rule 26-722)", "capacitor conductor حداقل 135% از rated current (Rule 26-210)", "min 2 outdoor duplex receptacle در یک dwelling اجباری است (Rule 26-724)", "transformer secondary fault current = secondary full-load current (FLA) ÷ per-unit impedance"], "traps_fa": ["اینکه Rule 26-712 را '1.8 m apart' بخوانی — نه! آن 1.8 m فاصلهٔ هر point تا یک receptacle است؛ پس خودِ receptacle ها تا 3.6 m از هم فاصله می‌گیرند", "زدنِ GFCI روی dedicated receptacle یک stationary appliance (washer پشتِ دستگاه، sump pump) — اینها exception دارند", "از یاد بردنِ trigger همان 2.5 m از grade برای outdoor GFCI (Rule 26-714)", "قاطی کردنِ 135% capacitor conductor (Rule 26-210) با 125% branch موتور (Rule 28-106) — این دو عددِ خیلی شبیه به هم سرِ امتحان زمینت می‌زنند", "استفاده از ≤750 V column برای transformer OCPD در حالی که primary بالای >750 V است (Table 50 column فرق دارد ← مثلاً تا 300% مجاز می‌شود)", "handle height: حواست باشد max یعنی 1.7 m، نه 2.1 m و نه 1.5 m"], "method_fa": ["receptacle spacing/placement در dwelling ← Rule 26-712 (همان 1.8 m / 3.6 m، به‌علاوهٔ counter و island rules).", "GFCI question ← نزدیکِ sink (1.5 m) یا outdoor تا 2.5 m از grade ← Class A GFCI؛ بعد dedicated-appliance exception ها را چک کن.", "AFCI / dedicated circuit در dwelling ← Rule 26-722.", "capacitor ← Rule 26-210: conductor ≥135% از rated current؛ و rated current = kVA ÷ (V × √3 برای 3-phase).", "transformer OCPD ← اول primary current را در بیاور، بعد Table 50 % را بزن (مراقبِ ≤750 V در برابرِ >750 V باش) و با Table 13 round کن.", "transformer fault/interrupting rating ← secondary FLA ÷ per-unit impedance."], "mnemonic_fa": "receptacle ها: 1.8 تا یک point، پس 3.6 بینِ خودشان؛ panel handle 1.7؛ range 130؛ outdoor GFCI تا 2.5 از grade."}, {"section": 28, "name": "Motors & Control", "block": "D", "qcount": 45, "importance": 5, "summary": "The hardest block — calculation- and diagram-heavy. Everything starts from the Table 44/45 FLC (NOT the nameplate) for conductors and branch overcurrent; only the overload comes from the nameplate FLA.", "keyTables": [{"ref": "Table 44", "stars": 5, "what": "3-phase motor full-load current (FLC) by hp & voltage", "use": "USE THIS for conductors and branch OCPD, NOT the nameplate", "what_fa": "full-load current (FLC / جریانِ بارِ کامل) موتورِ 3-phase بر حسبِ hp و voltage", "use_fa": "برای conductor ها و branch OCPD همیشه از همین Table 44 بخوان، not from the motor nameplate — این مهم‌ترین rule بلوکِ موتور است"}, {"ref": "Table 45", "stars": 4, "what": "Single-phase motor FLC by hp & voltage", "use": "single-phase equivalent of Table 44", "what_fa": "FLC موتورِ single-phase بر حسبِ hp و voltage", "use_fa": "همان نقشِ Table 44 را دارد، فقط برای single-phase motor"}, {"ref": "Table 29", "stars": 5, "what": "Max motor branch-circuit fuse/breaker as % of FLC", "use": "time-delay fuse 175% (225% won't-start), non-time-delay 300%, inverse-time CB 250%, instantaneous-trip 1300%", "what_fa": "max branch-circuit fuse/breaker موتور، به‌صورتِ % از FLC", "use_fa": "time-delay fuse 175% (اگر موتور راه نیفتد تا 225%)، non-time-delay fuse 300%، inverse-time CB 250%، و instantaneous-trip 1300%"}, {"ref": "Table 27", "stars": 4, "what": "Duty-cycle / non-continuous service percentages", "use": "replaces the 125% continuous factor for short-time/intermittent/periodic/varying duty", "what_fa": "duty-cycle / non-continuous service percentages (سرویسِ دوره‌ای / غیرپیوسته)", "use_fa": "وقتی موتور short-time/intermittent/periodic/varying duty کار می‌کند، به‌جای 125% continuous factor از % همین Table 27 استفاده کن — چون موتورِ non-continuous دائم گرم نمی‌ماند"}], "keyRules": [{"ref": "Rule 28-106", "stars": 5, "what": "Branch-circuit conductor = 125% of FLC", "note": "FLC from Table 44/45; continuous duty", "what_fa": "branch-circuit conductor موتور = 125% از FLC", "note_fa": "FLC را از Table 44/45 بگیر (not from the nameplate)؛ این 125% برای continuous duty است"}, {"ref": "Rule 28-108", "stars": 5, "what": "Feeder conductor for a group of motors", "note": "125% of the largest motor FLC + sum of the other motors' FLCs (duty-adjusted via Table 27)", "what_fa": "feeder conductor برای group of motors", "note_fa": "فقط largest motor یک 125% می‌گیرد: 125% از FLC بزرگ‌ترین موتور + sum of the other motors' FLCs (که اگر duty-cycle باشند با Table 27 تنظیم می‌شوند)"}, {"ref": "Rule 28-200", "stars": 5, "what": "Branch-circuit overcurrent (max % from Table 29)", "note": "next size NOT exceeding by default; next-higher only if motor won't start", "what_fa": "branch-circuit overcurrent (max % از Table 29)", "note_fa": "default این است که به next standard size که not exceeding باشد round کنی؛ فقط در صورتی به next-higher size برو که موتور راه نیفتد (won't start)"}, {"ref": "Rule 28-306", "stars": 5, "what": "Overload sized from NAMEPLATE FLA", "note": "×1.25 if SF ≥1.15 or temp-rise ≤40 °C, else ×1.15; single-phase = 1 device", "what_fa": "overload (اضافه‌بار) از nameplate FLA حساب می‌شود، not from the table", "note_fa": "اگر service factor SF≥1.15 باشد یا temp-rise ≤40 °C، ×1.25؛ در غیرِ این صورت ×1.15. برای single-phase motor هم 1 overload device کافی است"}, {"ref": "Rule 28-604", "stars": 4, "what": "Disconnecting means location", "note": "within sight of AND ≤9 m from the motor/equipment", "what_fa": "disconnecting means location (محلِ نصبِ disconnect)", "note_fa": "هم باید within sight باشد و هم ≤9 m از خودِ motor/equipment — هر دو شرط با هم"}, {"ref": "Rule 28-204", "stars": 3, "what": "Feeder overcurrent for a group of motors", "note": "largest-motor branch OCPD + remaining motor FLCs, to next size not exceeding", "what_fa": "feeder overcurrent برای group of motors", "note_fa": "largest-motor branch OCPD + FLC بقیهٔ موتورها، و بعد round به next size که not exceeding باشد"}, {"ref": "Rule 28-300", "stars": 3, "what": "Air-conditioning / refrigeration (compressor) sizing", "note": "size on marked rated-load current; LRC = 6×FLC if not marked", "what_fa": "air-conditioning / refrigeration (compressor) sizing", "note_fa": "بر اساسِ marked rated-load current روی nameplate سایز کن؛ و اگر locked-rotor current (LRC) نوشته نشده بود، آن را 6×FLC در نظر بگیر"}], "mustKnow": ["FLC from Table 44 (3-φ) / Table 45 (1-φ) — NOT the nameplate", "Branch conductor = 125% of FLC (28-106)", "Feeder = 125% of largest motor FLC + sum of remaining motor FLCs (28-108)", "Overload from NAMEPLATE FLA: ×1.25 (SF≥1.15 / rise≤40 °C) or ×1.15 (28-306)", "Table 29 branch OCPD: time-delay fuse 175% (225% won't-start), non-time-delay 300%, inverse-time CB 250%, instantaneous-trip 1300%", "Default: round OCPD to next size NOT exceeding; go higher only if the motor will not start", "Disconnect within sight AND ≤9 m (28-604)", "Duty-cycle service uses Table 27 % instead of the 125% continuous factor", "Single-phase motor needs 1 overload device"], "traps": ["Using the nameplate FLA for conductors/branch fuses (must use Table 44/45 FLC)", "Using Table 44 FLC for the overload (overload uses NAMEPLATE FLA, 28-306)", "Overcurrent vs overload confusion: overcurrent (fuse/breaker) protects the WIRE; overload (thermal) protects the MOTOR", "Rounding the OCPD to the next-HIGHER size when the motor isn't stated as 'won't start' — default is next size NOT exceeding", "Applying 125% to a duty-cycle motor — use the Table 27 percentage instead", "DC motor FLC comes from Table D2 (Appendix D), not Table 44", "Feeder: only the LARGEST motor gets the 125%; the rest are added at their plain FLC"], "mnemonic": "Wires & fuses = Table 44 (×1.25 / Table 29); Overload = nameplate. OverCURRENT protects Conductors, overLOAD protects the motor.", "method": ["Branch conductor: Table 44/45 FLC × 1.25 (28-106).", "Branch OCPD: FLC × Table 29 % for the device type; default next standard size NOT exceeding (28-200).", "Overload: nameplate FLA × 1.25 or 1.15 per 28-306 (count devices: 1 for single-phase).", "Feeder (group): 125% of largest FLC + sum of other FLCs; apply Table 27 for any duty-cycle motors (28-108).", "Feeder OCPD: largest-motor branch OCPD + remaining FLCs, next size not exceeding (28-204).", "Disconnect: within sight and ≤9 m (28-604).", "Compressor/DC: marked rated-load current / Table D2 FLC respectively."], "examples": ["S28-012", "S28-008", "S28-025", "S28-022", "S28-003", "S28-015"], "keywords": [{"kw": "\"motor full-load current / FLC\"", "jump": "Table 44 (3-φ) / Table 45 (1-φ)", "why": "NOT the nameplate", "stars": 5, "why_fa": "از Table 44/45 بخوان، not from the nameplate"}, {"kw": "\"motor branch-circuit conductor size\"", "jump": "Rule 28-106", "why": "125% of FLC (Table 44/45)", "stars": 5, "why_fa": "125% از FLC (Table 44/45)"}, {"kw": "\"max fuse / breaker for a motor branch\"", "jump": "Table 29 + Rule 28-200", "why": "TD fuse 175% (225% won't-start), non-TD 300%, inverse CB 250%, inst-trip 1300%", "stars": 5, "why_fa": "time-delay fuse 175% (225% اگر won't-start)، non-time-delay 300%، inverse-time CB 250%، instantaneous-trip 1300%"}, {"kw": "\"motor overload / heater size\"", "jump": "Rule 28-306", "why": "from NAMEPLATE FLA ×1.25 (SF≥1.15) or ×1.15", "stars": 5, "why_fa": "از nameplate FLA: ×1.25 (اگر SF≥1.15) وگرنه ×1.15"}, {"kw": "\"feeder for a group of motors\"", "jump": "Rule 28-108", "why": "125% largest FLC + sum of other FLCs", "stars": 5, "why_fa": "125% از largest motor FLC + sum of other FLCs"}, {"kw": "\"instantaneous-trip / magnetic-only breaker %\"", "jump": "Table 29", "why": "1300% of FLC", "stars": 4, "why_fa": "1300% از FLC — همین یک عدد"}, {"kw": "\"time-delay fuse, motor won't start\"", "jump": "Rule 28-200 + Table 29", "why": "raise 175% → up to 225% only if it won't start", "stars": 4, "why_fa": "از 175% شروع کن؛ تا 225% فقط در صورتی که motor won't-start"}, {"kw": "\"duty cycle / intermittent / short-time motor\"", "jump": "Table 27", "why": "use the duty % instead of 125% continuous", "stars": 4, "why_fa": "به‌جای 125% continuous از duty % استفاده کن"}, {"kw": "\"motor disconnect distance / location\"", "jump": "Rule 28-604", "why": "within sight AND ≤9 m", "stars": 4, "why_fa": "هم within sight، هم ≤9 m — هر دو با هم"}, {"kw": "\"number of overload devices (single-phase)\"", "jump": "Rule 28-306 / Table 14", "why": "single-phase = 1 device", "stars": 3, "why_fa": "single-phase فقط 1 overload device"}, {"kw": "\"overload multiplier, service factor not marked\"", "jump": "Rule 28-306", "why": "115% of nameplate FLA", "stars": 3, "why_fa": "115% از nameplate FLA"}, {"kw": "\"feeder overcurrent for motor group\"", "jump": "Rule 28-204", "why": "largest-motor branch OCPD + remaining FLCs", "stars": 3, "why_fa": "largest-motor branch OCPD + remaining FLCs"}, {"kw": "\"compressor / refrigeration / A-C motor sizing\"", "jump": "Rule 28-300 series", "why": "size on marked rated-load current; LRC = 6×FLC if unmarked", "stars": 3, "why_fa": "بر اساسِ marked rated-load current؛ اگر LRC نوشته نشده، 6×FLC"}, {"kw": "\"DC motor conductor / breaker\"", "jump": "Table D2 (Appendix D) + Table 29", "why": "DC FLC from Table D2, not Table 44", "stars": 3, "why_fa": "DC motor FLC از Table D2 می‌آید، not from Table 44"}, {"kw": "\"motor supply conductor insulation temp\"", "jump": "Rule 28-104 / Table 37", "why": "by motor enclosure/insulation class", "stars": 2, "why_fa": "بسته به enclosure/insulation class موتور"}, {"kw": "\"control circuit / holding (seal-in) contact\"", "jump": "Section 28 control (theory)", "why": "maintaining contact in parallel with start button", "stars": 3, "why_fa": "holding/seal-in contact موازی با start button تا control circuit وصل بماند"}, {"kw": "\"low-voltage release vs protection (auto restart)\"", "jump": "Section 28 control (theory)", "why": "LV release = auto restart; LV protection = stays off", "stars": 2, "why_fa": "low-voltage release = motor خودش auto restart می‌شود؛ low-voltage protection = خاموش می‌ماند تا دستی روشنش کنی"}, {"kw": "\"locked-rotor current\"", "jump": "Table 28", "why": "LRC by hp/voltage; or 6×FLC when unmarked", "stars": 2, "why_fa": "LRC را از Table 28 بر حسبِ hp/voltage بخوان؛ یا اگر نوشته نشده، 6×FLC"}], "summary_fa": "سخت‌ترین بلوکِ امتحان است — پُر از calculation و diagram. کلِ کار یک کلیدِ طلایی دارد: برای conductor ها و branch overcurrent همیشه از Table 44/45 FLC شروع کن، not from the motor nameplate؛ تنها جایی که سراغِ nameplate می‌روی، محاسبهٔ overload است. همین یک نکته نیمِ سوال‌های این بلوک را درست می‌کند.", "mustKnow_fa": ["FLC را از Table 44 (3-phase) / Table 45 (1-phase) بخوان — not from the nameplate", "branch conductor = 125% از FLC (Rule 28-106)", "feeder = 125% از FLC بزرگ‌ترین موتور + sum of remaining motor FLCs (Rule 28-108)", "overload از nameplate FLA: ×1.25 (اگر service factor SF≥1.15 یا rise≤40 °C) وگرنه ×1.15 (Rule 28-306)", "branch OCPD از Table 29: time-delay fuse 175% (225% اگر won't-start)، non-time-delay 300%، inverse-time CB 250%، instantaneous-trip 1300%", "default: OCPD را به next standard size که not exceeding باشد round کن؛ فقط وقتی motor راه نمی‌افتد بالاتر برو", "disconnect هم within sight و هم ≤9 m (Rule 28-604)", "برای duty-cycle service به‌جای 125% continuous factor از % همان Table 27 استفاده کن", "single-phase motor فقط 1 overload device لازم دارد"], "traps_fa": ["برداشتنِ nameplate FLA برای conductor ها/branch fuse — اینجا باید Table 44/45 FLC را به کار ببری", "برعکسش هم trap است: استفاده از Table 44 FLC برای overload — overload همیشه از nameplate FLA می‌آید (Rule 28-306)", "قاطی کردنِ overcurrent با overload: overcurrent (fuse/breaker) از WIRE محافظت می‌کند، اما thermal overload از خودِ MOTOR", "وقتی نگفته‌اند motor 'won't start'، نباید OCPD را به next-higher size round کنی — default همان next size که not exceeding باشد است", "زدنِ 125% به یک duty-cycle motor — به‌جایش باید Table 27 percentage را به کار ببری", "DC motor FLC از Table D2 (Appendix D) می‌آید، not from Table 44", "در feeder فقط largest motor یک 125% می‌گیرد؛ بقیه با plain FLC خودشان جمع می‌شوند"], "method_fa": ["branch conductor: Table 44/45 FLC × 1.25 (Rule 28-106).", "branch OCPD: FLC × Table 29 % بسته به device type؛ default همان next standard size که not exceeding باشد (Rule 28-200).", "overload: nameplate FLA × 1.25 یا 1.15 طبقِ Rule 28-306 (count devices: برای single-phase همان 1 تا).", "feeder (group): 125% از largest FLC + sum of other FLCs؛ برای duty-cycle motor ها حتماً Table 27 را اعمال کن (Rule 28-108).", "feeder OCPD: largest-motor branch OCPD + remaining FLCs، round به next size که not exceeding باشد (Rule 28-204).", "disconnect: within sight و ≤9 m (Rule 28-604).", "compressor/DC: به‌ترتیب marked rated-load current / Table D2 FLC."], "mnemonic_fa": "wires & fuses = Table 44 (×1.25 / Table 29)؛ overload = nameplate. overCURRENT سراغِ conductor هاست، overLOAD سراغِ خودِ motor."}, {"section": "occ", "name": "Occupational / Safety Skills (Block A)", "block": "A", "qcount": 62, "importance": 5, "summary": "Block A is the largest no-codebook block: PPE, lockout, transformer hazards, generators, PV, VFDs, HVAC controls, torque specs and troubleshooting. Mostly trade-knowledge recall with a few fault-current and signal calcs - lots of fast marks.", "summary_fa": "Block A بزرگ‌ترین بلوکی است که بدونِ کتابِ Code جواب می‌دهی: PPE، lockout، خطراتِ ترانسفورمر، ژنراتور، PV، VFD، کنترل‌های HVAC، مشخصاتِ گشتاور (torque) و عیب‌یابی. بیشترش یادآوریِ دانشِ فنیِ کار است با چند محاسبه‌ی fault-current و سیگنال — یعنی پر است از نمره‌های سریع، اگر سریع و مطمئن جواب بدهی.", "keyTables": [{"ref": "Table D7", "stars": 3, "what": "Tightening torque for connecting hardware", "what_fa": "tightening torque (گشتاورِ سفت‌کردن) برای connecting hardware (یراقِ اتصال)", "use": "look up bolt size -> N.m (e.g. 1/2 in = 54 N.m)", "use_fa": "اندازه‌ی bolt را پیدا کن، عددِ N.m را بردار (مثلاً 1/2 in می‌شود 54 N.m)"}, {"ref": "Appendix D", "stars": 2, "what": "Torque / reference engineering data", "what_fa": "reference engineering data (داده‌های مهندسیِ مرجع)، از جمله torque", "use": "supports torque-spec and fault-current questions", "use_fa": "پشتوانه‌ی سوال‌های مربوط به torque spec و fault current است"}], "keyRules": [{"ref": "Rule 4-024 / 4-036", "stars": 2, "what": "Identified (neutral) conductor colour", "what_fa": "رنگِ identified conductor (همان neutral)", "note": "white/grey for #2 AWG and smaller - the one Section reference in this block's analysis", "note_fa": "برای #2 AWG و کوچک‌تر، رنگش white یا grey است؛ این تنها ارجاعِ Section در کلِ این بلوک است"}, {"ref": "Section 64", "stars": 2, "what": "Renewable energy / PV backfeed breaker placement", "what_fa": "renewable energy؛ محلِ نصبِ backfeed breaker سیستمِ PV", "note": "back-fed PV breaker at the opposite end from the main (120% rule)", "note_fa": "back-fed PV breaker را در opposite end از main می‌گذاری، نه نزدیکش (همان 120% busbar rule)"}, {"ref": "Section 46", "stars": 1, "what": "Emergency systems wiring methods", "what_fa": "wiring methods برای emergency systems", "note": "life-safety supply conductors in protected raceway", "note_fa": "life-safety supply conductors باید داخلِ protected raceway باشند"}], "mustKnow": ["Lockout step 1 = IDENTIFY all potential energy sources; then isolate, lock, and verify zero energy.", "Transformer hazards: primary = back-feed; secondary = arc flash (high available fault current).", "Torque: 1/2 in connecting hardware = 54 N.m; 1/4 in HVAC bolt = 8 N.m (Table D7 / mfr data).", "Available short-circuit current = secondary FLC / %Z (e.g. 833 A / 0.03 = 27.8 kA).", "4-20 mA signal: output = 4 mA + (%open x 16 mA span); 85% = 17.6 mA.", "Cutting/grinding metal tray -> add a FACE SHIELD; HV rubber gloves retest 12 months in storage / 6 months in service.", "Class A GFCI trips at 5 mA ground-fault current.", "Bump test = checks direction of rotation. Off-delay timer = keeps fan running after shutdown.", "Exit signs / smoke alarms: REQUIREMENT is in the National Building Code; electrical sizing is in the CEC."], "mustKnow_fa": ["گامِ اولِ lockout همیشه شناسایی (IDENTIFY) همه‌ی منابعِ انرژی است؛ بعد جداسازی، بعد قفل، و در آخر تاییدِ صفر بودنِ انرژی.", "خطراتِ ترانسفورمر: سمتِ اولیه (primary) خطرش back-feed است؛ سمتِ ثانویه (secondary) خطرش arc flash است (چون جریانِ خطای در دسترس بالاست).", "گشتاور: یراقِ اتصالِ 1/2 in می‌شود 54 N.m؛ پیچِ 1/4 in در HVAC می‌شود 8 N.m (از Table D7 یا داده‌ی سازنده).", "جریانِ اتصال‌کوتاهِ در دسترس = FLCِ ثانویه تقسیم بر %Z (مثلاً 833 A تقسیم بر 0.03 می‌شود 27.8 kA).", "سیگنالِ 4-20 mA: خروجی = 4 mA به‌علاوه‌ی (درصدِ باز ضربدر گستره‌ی 16 mA)؛ پس 85٪ می‌شود 17.6 mA.", "موقعِ برش یا سنگ‌زنیِ سینیِ فلزی، حتماً سپرِ صورت (FACE SHIELD) هم اضافه کن؛ و دستکشِ لاستیکیِ HV هر 12 ماه در انبار و هر 6 ماه در حالِ استفاده باید دوباره تست شود.", "GFCIِ کلاس A سرِ جریانِ خطای زمینِ 5 mA قطع می‌کند.", "Bump test برای بررسیِ جهتِ چرخش است؛ و تایمرِ Off-delay فن را بعد از خاموش شدنِ موتور یک‌مدت روشن نگه می‌دارد.", "تابلوهای exit و دتکتورهای دود: الزامِ نصب‌شان در National Building Code است، اما سایزبندیِ برقی‌اش در CEC؛ دقت کن سوال کدام را می‌خواهد."], "traps": ["Lockout: the first step is identify energy sources, NOT install the hasp or complete the log.", "Primary hazard is back-feed; secondary hazard is arc flash - don't swap them.", "Split receptacle that trips instantly: the break-off tab on the UNGROUNDED (hot) side was left intact, shorting the phases.", "Heating cable resistance drops after install = a staple penetrated the cable (fault), not a sensor failure.", "VFD startup: program parameters BEFORE any rotation/bump test; confirm motor is free first.", "Exit-sign authority = NBC, not the CEC (read which document the question asks for)."], "traps_fa": ["در lockout گامِ اول identify کردنِ energy sources است، نه نصبِ hasp و نه پر کردنِ log؛ این جایی است که گزینه‌ی فریبنده می‌گذارند.", "خطرِ primary همان back-feed است و خطرِ secondary همان arc flash؛ مراقب باش این دو را جابه‌جا نکنی.", "split receptacle که آنی trip می‌کند: یعنی break-off tab سمتِ UNGROUNDED (همان hot) را نشکسته‌اند و phase‌ها را به هم short کرده.", "افتِ resistance یک heating cable بعد از نصب یعنی یک staple (منگنه) رفته توی cable و insulation را زده (fault)، نه اینکه sensor خراب شده باشد.", "VFD startup: اول مطمئن شو motor آزاد می‌چرخد، بعد parameters را program کن، و فقط آن‌وقت rotation test یا bump test بزن؛ ترتیبش مهم است.", "authority تابلوی exit همان NBC است نه CEC؛ خوب بخوان که سوال سراغِ کدام document را می‌گیرد."], "mnemonic": "Lockout = I-I-V (Identify, Isolate, Verify). Transformer: Primary Pushes back (back-feed), Secondary Sparks (arc flash). 4-20 mA: '4 plus 16'.", "mnemonic_fa": "Lockout را با I-I-V بسپار: Identify، Isolate، Verify. ترانسفورمر هم: اولیه «فشار به عقب» می‌دهد (Primary Pushes back = back-feed)، ثانویه «جرقه می‌زند» (Secondary Sparks = arc flash). و برای سیگنال یادت باشد: «4 به‌علاوه‌ی 16».", "method": ["Most Block A questions are pure trade recall - answer fast, flag none, bank time for the calc-heavy blocks.", "For hazard/safety: name the energy and the protection (lockout, PPE, arc-flash/back-feed).", "For controls (VFD, HVAC sequence, timers): order the steps logically - prove safe/free first, program, then test.", "For the few calcs: fault current = FLC / %Z; 4-20 mA = 4 + (span x percent); torque = look up the bolt size."], "method_fa": ["بیشترِ سوالاتِ Block A trade recall خالص است؛ سریع جواب بده و flag نگذار، تا وقتت برای بلوک‌های پرمحاسبه بماند.", "در سوالاتِ hazard و safety، نوعِ energy و نوعِ protection را با هم نام ببر (lockout، PPE، arc-flash یا back-feed).", "در سوالاتِ control (VFD، HVAC sequence، timers) گام‌ها را منطقی مرتب کن: اول safe و free بودن را ثابت کن، بعد program، آخر test.", "برای آن چند محاسبه‌ی انگشت‌شمار: fault current = FLC تقسیم بر %Z؛ سیگنالِ 4-20 mA = 4 به‌علاوه‌ی (span ضربدر percent)؛ و torque را از روی اندازه‌ی bolt پیدا کن."], "examples": ["OCC-001", "OCC-002", "OCC-003", "OCC-010", "OCC-026", "OCC-030"], "keywords": [{"kw": "\"torque spec / N.m for hardware\"", "jump": "Table D7 (Appendix D)", "why": "1/2 in = 54 N.m, 1/4 in HVAC = 8 N.m", "why_fa": "این دو عددِ torque پرتکرار را حفظ کن: 1/2 in می‌شود 54 N.m، و 1/4 in در HVAC می‌شود 8 N.m", "stars": 4}, {"kw": "\"lock-out first step\"", "jump": "Identify energy sources (LOTO)", "why": "identify before isolate/lock/verify", "why_fa": "اول identify، بعد isolate و lock و verify", "stars": 4}, {"kw": "\"transformer hazard primary vs secondary\"", "jump": "Back-feed (primary) / arc flash (secondary)", "why": "classic paired safety question", "why_fa": "همان سوالِ safety جفتیِ کلاسیک: primary همان back-feed، secondary همان arc flash", "stars": 4}, {"kw": "\"PPE for grinding / cutting tray\"", "jump": "Face shield", "why": "flying metal particles and sparks", "why_fa": "به‌خاطرِ پرتابِ براده‌ی metal و sparks، یک face shield لازم است", "stars": 3}, {"kw": "\"available fault / short-circuit current\"", "jump": "FLC / %Z", "why": "interrupting rating must exceed it", "why_fa": "interrupting rating دستگاه باید از این جریان بیشتر باشد", "stars": 3}, {"kw": "\"back-fed PV breaker location\"", "jump": "Section 64 (opposite end from main)", "why": "120% busbar / backfeed rule", "why_fa": "به‌خاطرِ 120% busbar rule، back-fed breaker در opposite end از main می‌نشیند", "stars": 3}, {"kw": "\"VFD startup sequence\"", "jump": "Program params -> bump/rotation test", "why": "set parameters before any rotation", "why_fa": "اول parameters را program کن، بعد سراغِ هر rotation برو", "stars": 3}, {"kw": "\"generator won't start (cold / outage)\"", "jump": "Battery heater / charger failure", "why": "cold or dead batteries can't crank", "why_fa": "battery سرد یا خالی توانِ crank زدن ندارد", "stars": 3}, {"kw": "\"4-20 mA control signal\"", "jump": "4 mA + percent x 16 mA span", "why": "85% open = 17.6 mA", "why_fa": "مثلاً 85٪ open می‌شود 17.6 mA", "stars": 3}, {"kw": "\"overload heater won't reset\"", "jump": "Melted solder pot (eutectic relay)", "why": "won't latch until cooled/replaced", "why_fa": "تا وقتی این eutectic relay خنک یا تعویض نشود، latch نمی‌شود", "stars": 3}, {"kw": "\"split receptacle / breaker trips instantly\"", "jump": "Broken tab on ungrounded side", "why": "intact hot tab shorts the phases", "why_fa": "چون tab سمتِ hot سالم مانده، phase‌ها را short می‌کند", "stars": 3}, {"kw": "\"HVAC heating sequence / high-limit\"", "jump": "Purge -> gas valve -> damper/blower", "why": "no airflow -> high-limit opens, gas de-energizes", "why_fa": "اگر airflow نباشد، high-limit باز می‌شود و gas valve قطع می‌شود", "stars": 3}, {"kw": "\"GFCI trip current / pool deck\"", "jump": "Class A = 5 mA", "why": "won't reset with power & no fault = faulty device", "why_fa": "اگر با وجودِ power و نبودِ fault، GFCI ری‌ست نشود، یعنی خودِ device معیوب است", "stars": 2}, {"kw": "\"bump test\"", "jump": "Direction of rotation", "why": "momentary energize to confirm rotation", "why_fa": "energize لحظه‌ای فقط برای دیدنِ direction of rotation", "stars": 2}, {"kw": "\"off-delay vs on-delay timer\"", "jump": "Off-delay = run after shutdown", "why": "20 s cooling fan after motor stops", "why_fa": "Off-delay یعنی cooling fan مثلاً 20 s بعد از توقفِ motor هم کار می‌کند", "stars": 2}, {"kw": "\"3-wire control / holding contact\"", "jump": "Low-voltage protection", "why": "coil drops out on voltage loss, needs restart", "why_fa": "با افتِ voltage، coil رها می‌شود و برای restart باید دوباره دکمه بزنی (low-voltage protection)", "stars": 2}, {"kw": "\"in-floor heating cable resistance drop\"", "jump": "Staple penetrated cable", "why": "insulation fault lowers resistance", "why_fa": "یک insulation fault مقدارِ resistance را پایین می‌آورد", "stars": 2}, {"kw": "\"HV rubber glove retest interval\"", "jump": "12 mo storage / 6 mo in service", "why": "periodic dielectric retest", "why_fa": "dielectric retest دوره‌ای: 12 ماه در storage، 6 ماه در in service", "stars": 2}, {"kw": "\"who coordinates sub-trades / schedule\"", "jump": "General contractor", "why": "site coordination question", "why_fa": "سوالِ site coordination؛ این کار با general contractor است", "stars": 2}, {"kw": "\"rough-in inspection timing\"", "jump": "Before any work is concealed", "why": "drywall/concrete cover-up trigger", "why_fa": "قبل از اینکه کار با drywall یا concrete پوشانده شود (rough-in inspection)", "stars": 2}, {"kw": "\"exit signs / smoke alarm authority\"", "jump": "National Building Code (not CEC)", "why": "requirement vs electrical sizing", "why_fa": "requirement نصب با NBC است، electrical sizing با CEC", "stars": 2}, {"kw": "\"hotspots in connections\"", "jump": "Infrared / thermal camera", "why": "detects loose/high-resistance heat", "why_fa": "گرمای connectionهای loose و high-resistance را با یک thermal camera پیدا می‌کنی", "stars": 1}, {"kw": "\"fasteners (concrete / strut)\"", "jump": "Drop-in anchor / strut spring nuts", "why": "panel-to-concrete vs equipment-to-strut", "why_fa": "اتصالِ panel به concrete در مقابلِ اتصالِ equipment به strut", "stars": 1}, {"kw": "\"neutral conductor identification\"", "jump": "Rule 4-024/4-036 (white, <=#2 AWG)", "why": "identified-conductor colour", "why_fa": "رنگِ identified conductor", "stars": 1}]}]};
